--[[
    ==================================================================
    IDENTICAL HUB V2 - HEAVYWEIGHT FISHING (MODULAR BUILD)
    Architecture: Modular V2 (Clean State Machine • Strict Combo)
    Auto-generated by build.py - Do not edit directly!
    ==================================================================
--]]

local __modules = {}
local __cache = {}
local function __require(modName)
    if __cache[modName] ~= nil then
        return __cache[modName]
    end
    local fn = __modules[modName]
    if not fn then
        error("[Identical V2] Module not found: " .. tostring(modName))
    end
    local res = fn()
    __cache[modName] = res
    return res
end

__modules["combo.executor"] = function()
--[[
    v2/combo/executor.lua
    Multi-Layer Skill Casting Engine with Safety Protection
--]]

local Services = __require("core.services")
local Events = Services.Events
local LocalPlayer = Services.LocalPlayer
local VirtualInputManager = Services.VirtualInputManager
local Tracker = __require("combo.tracker")

local Executor = {}

function Executor.CastSkill(sk, config, ticketQuestState)
    if not sk or sk == "" or sk == "Tắt" then return false end
    local cleanKey = sk:match("([ZXCVzxcv])") or sk
    cleanKey = cleanKey:upper()

    -- 1. KHÓA BẢO VỆ CHIÊU C (Tránh dùng nhầm chiêu tốn tài nguyên trừ khi người chơi cài đặt rõ ràng)
    if cleanKey == "C" and config then
        local userChoseC = false
        if config.TicketQuickSkill and config.TicketQuickSkill:find("[Cc]") then userChoseC = true end
        if config.TicketSkillKey and config.TicketSkillKey:find("[Cc]") then userChoseC = true end
        if config.TrainSkill and config.TrainSkill:find("[Cc]") then userChoseC = true end
        if config.QuickCatchSkill == "C" or config.OpenerSkill == "C" or config.EmergencyHealSkill == "C" then userChoseC = true end
        if (config.SmartComboEnabled or config.AutoSkills) and config.LoopSkills and config.LoopSkills:find("[Cc]") then
            userChoseC = true
        end
        if not userChoseC then
            return false
        end
    end

    -- 2. KHÓA BẢO VỆ NHIỆM VỤ VÉ (Nếu đang làm quest 100 cá hoặc 100 skill thì chỉ dùng chiêu được chỉ định)
    if ticketQuestState and ticketQuestState.currentQuestType then
        local curQ = ticketQuestState.currentQuestType
        if curQ == "skill_100" and config and config.TicketSkillKey then
            local allowed = config.TicketSkillKey:match("([ZXCVzxcv])%s*$")
            allowed = allowed and allowed:upper() or "Z"
            if cleanKey ~= allowed then return false end
        elseif curQ == "fish_100" and config and config.TicketQuickSkill then
            local allowed = config.TicketQuickSkill:match("([ZXCVzxcv])%s*$")
            allowed = allowed and allowed:upper() or "V"
            if cleanKey ~= allowed then return false end
        end
    end

    -- 3. TẦNG 1: Gửi RemoteEvent tới Server
    pcall(function()
        if Events then
            if Events:FindFirstChild("UseSkill") then
                Events.UseSkill:FireServer(cleanKey)
            end
            if Events:FindFirstChild("TriggerMinigameSkill") then
                Events.TriggerMinigameSkill:FireServer(cleanKey)
            end
        end
    end)

    -- 4. TẦNG 2: Giả lập phím bấm qua VirtualInputManager
    pcall(function()
        if VirtualInputManager and Enum.KeyCode[cleanKey] then
            VirtualInputManager:SendKeyEvent(true, Enum.KeyCode[cleanKey], false, game)
            task.wait(0.02)
            VirtualInputManager:SendKeyEvent(false, Enum.KeyCode[cleanKey], false, game)
        end
    end)

    -- 5. TẦNG 3: Giả lập kích hoạt trực tiếp nút bấm trên GUI Fishing
    pcall(function()
        local function clickBtn(btn)
            if not btn or not btn:IsA("GuiButton") or not btn.Visible then return false end
            if firesignal then
                if btn.Activated then firesignal(btn.Activated) end
                if btn.MouseButton1Click then firesignal(btn.MouseButton1Click) end
            end
            if getconnections then
                for _, c in ipairs(getconnections(btn.Activated)) do c:Fire() end
                for _, c in ipairs(getconnections(btn.MouseButton1Click)) do c:Fire() end
            end
            return true
        end

        local pGui = LocalPlayer:FindFirstChild("PlayerGui")
        local mGui = pGui and pGui:FindFirstChild("MainGui")
        local f = mGui and mGui:FindFirstChild("Fishing")
        if f then
            local sb = f:FindFirstChild("SkillButton")
            local fr = sb and sb:FindFirstChild("Frame")
            local btn = fr and fr:FindFirstChild(cleanKey)
            if btn and clickBtn(btn) then
                return
            end
            for _, d in ipairs(f:GetDescendants()) do
                if d:IsA("GuiButton") and (d.Name:upper() == cleanKey or (d.Name:upper():find("SKILL") and d.Name:upper():find(cleanKey))) then
                    clickBtn(d)
                end
            end
        end
    end)

    -- Ghi nhận thời gian tung chiêu
    Tracker.RecordSkillUsed(cleanKey)
    return true
end

return Executor

end

__modules["combo.state_machine"] = function()
--[[
    v2/combo/state_machine.lua
    Deterministic Sequential Combo Engine (Rebuilt from Scratch)
    Guarantees strict sequential execution: Z -> X -> V -> Z -> X -> V without skipping.
--]]

local Tracker = __require("combo.tracker")
local Executor = __require("combo.executor")

local StateMachine = {}

StateMachine.currentIndex = 1
StateMachine.lastActionTime = 0
StateMachine.minigameActive = false

-- 1. Parse combo string into a clean table of uppercase keys
function StateMachine.ParseComboKeys(comboStr)
    local keys = {}
    if not comboStr or comboStr == "" then return keys end
    for k in string.gmatch(comboStr, "([ZXCVzxcv])") do
        table.insert(keys, k:upper())
    end
    return keys
end

-- 2. Format preview for UI display (e.g. "Z ➔ X ➔ V")
function StateMachine.GetComboPreview(comboStr)
    local keys = StateMachine.ParseComboKeys(comboStr)
    if #keys == 0 then return "Trống (Chưa cài đặt)" end
    return table.concat(keys, " ➔ ") .. " (" .. tostring(#keys) .. " chiêu)"
end

-- 3. Minigame Event Hooks
function StateMachine.OnMinigameStart()
    StateMachine.minigameActive = true
    StateMachine.currentIndex = 1
    StateMachine.lastActionTime = 0
end

function StateMachine.OnMinigameEnd()
    StateMachine.minigameActive = false
    StateMachine.currentIndex = 1
    StateMachine.lastActionTime = 0
end

-- 4. Get Current Step Info for UI debug/status
function StateMachine.GetCurrentStatus(config)
    local keys = StateMachine.ParseComboKeys(config.LoopSkills or "Z, X, V")
    if #keys == 0 then return "Không có chiêu" end
    local idx = math.clamp(StateMachine.currentIndex, 1, #keys)
    local target = keys[idx] or "?"
    return string.format("Bước %d/%d: [%s]", idx, #keys, target)
end

-- 5. Main Execution Step (Called each tick during minigame)
function StateMachine.Step(config, fUI, playerHp, ticketQuestState)
    if not config or not config.SmartComboEnabled then return false end

    local now = tick()
    local effectDelay = tonumber(config.SkillEffectDelay) or 1.2

    -- 1. KIỂM TRA KHOẢNG CÁCH RA CHIÊU (Tránh spam liên tục làm nuốt chiêu của game)
    if (now - StateMachine.lastActionTime < effectDelay) then
        return false
    end

    -- 2. KIỂM TRA HOẠT ẢNH NHÂN VẬT (Nếu đang chém/tung chiêu thì chờ kết thúc)
    if config.SmartEffectAutoDetect and Tracker.IsCharacterCastingSkill() then
        return false
    end

    -- 3. CỨU NGUY HỒI MÁU KHẨN CẤP (Ưu tiên số 1 khi máu thấp, không làm mất thứ tự combo)
    local healKey = config.EmergencyHealSkill
    if healKey and healKey ~= "Tắt" and healKey ~= "" then
        healKey = healKey:match("([ZXCVzxcv])")
        if healKey then
            healKey = healKey:upper()
            local hpThreshold = tonumber(config.EmergencyHealHp) or 40
            if playerHp and playerHp <= hpThreshold then
                if Tracker.IsSkillReady(healKey, fUI) then
                    local castOk = Executor.CastSkill(healKey, config, ticketQuestState)
                    if castOk then
                        StateMachine.lastActionTime = now
                        return true -- Đã kích hoạt hồi máu, combo chính sẽ tiếp tục ở nhịp sau
                    end
                end
            end
        end
    end

    -- 4. XỬ LÝ CHUỖI COMBO TUẦN TỰ NGHIÊM NGẶT (STRICT ROTATION)
    local keys = StateMachine.ParseComboKeys(config.LoopSkills or "Z, X, V")
    if #keys == 0 then return false end

    -- Đảm bảo chỉ số con trỏ luôn nằm trong giới hạn hợp lệ
    if StateMachine.currentIndex < 1 or StateMachine.currentIndex > #keys then
        StateMachine.currentIndex = 1
    end

    local targetKey = keys[StateMachine.currentIndex]

    -- Kiểm tra xem chiêu hiện tại đã hồi xong hay chưa
    if Tracker.IsSkillReady(targetKey, fUI) then
        -- CHIÊU ĐÃ SẴN SÀNG -> THI TRIỂN
        local castSuccess = Executor.CastSkill(targetKey, config, ticketQuestState)
        if castSuccess then
            StateMachine.lastActionTime = now
            -- TỊNH TIẾN CON TRỎ SANG CHIÊU KẾ TIẾP TRONG CHUỖI
            StateMachine.currentIndex = (StateMachine.currentIndex % #keys) + 1
            return true
        end
    else
        -- CHIÊU CHƯA HỒI:
        -- TUYỆT ĐỐI CHỜ ĐỢI! KHÔNG NHẢY CÓC SANG CHIÊU KHÁC!
        -- KHÔNG THAY ĐỔI currentIndex!
        -- Việc này đảm bảo thứ tự luôn là: Z -> X -> V -> Z -> X -> V ...
        return false
    end

    return false
end

return StateMachine

end

__modules["combo.tracker"] = function()
--[[
    v2/combo/tracker.lua
    Accurate Skill Cooldown Tracking & Animation Detection
--]]

local Services = __require("core.services")
local LocalPlayer = Services.LocalPlayer

local Tracker = {}

-- 1. Default Base Cooldowns for Heavyweight Fishing skills
Tracker.defaultCooldowns = {
    Z = 2.5,
    X = 3.0,
    C = 5.0,
    V = 4.0
}

Tracker.usedTimes = {
    Z = 0,
    X = 0,
    C = 0,
    V = 0
}

Tracker.lastCastTime = 0

-- 2. Record Skill Used
function Tracker.RecordSkillUsed(key)
    if not key then return end
    local cleanKey = key:match("([ZXCVzxcv])") or key
    cleanKey = cleanKey:upper()
    local now = tick()
    Tracker.usedTimes[cleanKey] = now
    Tracker.lastCastTime = now
end

-- 3. Check if a skill is ready to be cast
function Tracker.IsSkillReady(key, fUI)
    if not key or key == "" or key == "Tắt" then return false end
    local cleanKey = key:match("([ZXCVzxcv])") or key
    cleanKey = cleanKey:upper()

    local now = tick()
    local lastUsed = Tracker.usedTimes[cleanKey] or 0
    local minCD = Tracker.defaultCooldowns[cleanKey] or 2.5

    -- 1. Kiểm tra mốc thời gian cooldown máy khách
    if (now - lastUsed < minCD) then
        return false
    end

    -- 2. Kiểm tra giao diện người dùng fUI (nếu có)
    if fUI then
        for _, desc in ipairs(fUI:GetDescendants()) do
            local nameUpper = desc.Name:upper()
            if nameUpper == cleanKey or (nameUpper:find("SKILL") and nameUpper:find(cleanKey)) or (nameUpper:find("SLOT") and nameUpper:find(cleanKey)) then
                if desc:GetAttribute("OnCooldown") == true or desc:GetAttribute("CD") == true then
                    return false
                end
                for _, child in ipairs(desc:GetDescendants()) do
                    if child:IsA("TextLabel") and child.Visible and child.Text ~= "" then
                        local cName = child.Name:lower()
                        local txt = child.Text
                        if not cName:find("dmg") and not cName:find("damage") and not cName:find("power") and not cName:find("level") and not cName:find("name") then
                            local cdWithS = txt:match("^%s*(%d+%.?%d*)%s*[sS]%s*$") or txt:match("^%s*(%d+%.?%d*)%s*sec%s*$")
                            if cdWithS then
                                local num = tonumber(cdWithS)
                                if num and num > 0 and num <= 999 then
                                    return false
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    return true
end

-- 4. Detect whether character is currently playing an attack skill animation
function Tracker.IsCharacterCastingSkill()
    local now = tick()
    if (now - Tracker.lastCastTime > 0.7) then
        return false
    end

    local char = LocalPlayer.Character
    if not char then return false end

    for _, att in ipairs({"UsingSkill", "SkillActive", "IsAttacking", "CastingSkill"}) do
        if char:GetAttribute(att) == true then
            return true
        end
    end

    local hum = char:FindFirstChildOfClass("Humanoid")
    local anim = hum and hum:FindFirstChildOfClass("Animator")
    if anim then
        local ok, tracks = pcall(function() return anim:GetPlayingAnimationTracks() end)
        if ok and tracks then
            for _, tr in ipairs(tracks) do
                if tr.IsPlaying and (tr.Priority == Enum.AnimationPriority.Action or tr.Priority == Enum.AnimationPriority.Action2 or tr.Priority == Enum.AnimationPriority.Action3 or tr.Priority == Enum.AnimationPriority.Action4) then
                    local animName = tr.Name:lower()
                    if not animName:find("fish") and not animName:find("rod") and not animName:find("reel") and not animName:find("cast") and not animName:find("idle") and not animName:find("hold") and not animName:find("walk") and not animName:find("run") then
                        if animName:find("skill") or animName:find("attack") or animName:find("special") or animName:find("slash") then
                            return true
                        end
                    end
                end
            end
        end
    end

    return false
end

function Tracker.Reset()
    Tracker.lastCastTime = 0
    for k in pairs(Tracker.usedTimes) do
        Tracker.usedTimes[k] = 0
    end
end

return Tracker

end

