-- 3. Account Persistence Helpers
local function sanitizeFilename(name)
    return name:gsub("[%c%p%s]", "_")
end

function ConfigModule.GetAccountConfigDir()
    local pName = LocalPlayer and LocalPlayer.Name or "DefaultUser"
    return "Identical/HeavyweightFishing/Configs/" .. sanitizeFilename(pName)
end

function ConfigModule.EnsureAccountConfigDir()
    if not makefolder then return false end
    pcall(makefolder, "Identical")
    pcall(makefolder, "Identical/HeavyweightFishing")
    pcall(makefolder, "Identical/HeavyweightFishing/Configs")
    local dir = ConfigModule.GetAccountConfigDir()
    pcall(makefolder, dir)
    return true
end

function ConfigModule.GetSavedConfigList()
    local list = {}
    if not listfiles then return list end
    ConfigModule.EnsureAccountConfigDir()
    local dir = ConfigModule.GetAccountConfigDir()
    local success, files = pcall(listfiles, dir)
    if success and type(files) == "table" then
        for _, f in ipairs(files) do
            local name = f:match("([^/\\]+)%.json$")
            if name then table.insert(list, name) end
        end
    end
    table.sort(list)
    return list
end

function ConfigModule.SaveAccountConfig(cfgName, uiControllers)
    if not writefile or not cfgName or cfgName == "" then return false, "Không hỗ trợ ghi file" end
    ConfigModule.EnsureAccountConfigDir()
    local path = ConfigModule.GetAccountConfigDir() .. "/" .. sanitizeFilename(cfgName) .. ".json"

    local serialize = {}
    for k, v in pairs(ConfigModule.Config) do
        if typeof(v) == "EnumItem" then
            serialize[k] = { __enum = tostring(v) }
        elseif typeof(v) == "CFrame" then
            serialize[k] = { __cframe = { v:GetComponents() } }
        elseif typeof(v) == "Vector3" then
            serialize[k] = { __vector3 = { v.X, v.Y, v.Z } }
        else
            serialize[k] = v
        end
    end

    local encoded = HttpService:JSONEncode(serialize)
    local ok, err = pcall(writefile, path, encoded)
    return ok, ok and ("Đã lưu cấu hình [" .. cfgName .. "]") or tostring(err)
end

function ConfigModule.LoadAccountConfig(cfgName, uiControllers)
    if not readfile or not cfgName or cfgName == "" then return false, "Không hỗ trợ đọc file" end
    local path = ConfigModule.GetAccountConfigDir() .. "/" .. sanitizeFilename(cfgName) .. ".json"
    if not (isfile and isfile(path)) then return false, "Không tìm thấy file" end

    local ok, content = pcall(readfile, path)
    if not ok or not content then return false, "Không thể đọc nội dung file" end

    local decOk, decoded = pcall(function() return HttpService:JSONDecode(content) end)
    if not decOk or type(decoded) ~= "table" then return false, "JSON lỗi" end

    for k, v in pairs(decoded) do
        if type(v) == "table" and v.__enum then
            local str = v.__enum
            local enumType, enumItem = str:match("Enum%.([^%.]+)%.([^%.]+)")
            if enumType and enumItem and Enum[enumType] and Enum[enumType][enumItem] then
                ConfigModule.Config[k] = Enum[enumType][enumItem]
            end
        elseif type(v) == "table" and v.__cframe then
            ConfigModule.Config[k] = CFrame.new(unpack(v.__cframe))
        elseif type(v) == "table" and v.__vector3 then
            ConfigModule.Config[k] = Vector3.new(unpack(v.__vector3))
        else
            ConfigModule.Config[k] = v
        end

        if uiControllers and uiControllers[k] and uiControllers[k].Set then
            pcall(function() uiControllers[k].Set(ConfigModule.Config[k], true) end)
        end
    end
    return true, "Đã tải cấu hình thành công!"
end

function ConfigModule.DeleteAccountConfig(cfgName)
    if not delfile or not cfgName or cfgName == "" then return false end
    local path = ConfigModule.GetAccountConfigDir() .. "/" .. sanitizeFilename(cfgName) .. ".json"
    if isfile and isfile(path) then
        return pcall(delfile, path)
    end
    return false
end

-- 4. Smart Combo Persistence (HeavyweightFishing_SmartCombo.json)
local SMART_COMBO_FILE = "HeavyweightFishing_SmartCombo.json"
local SMART_COMBO_KEYS = {
    "SmartComboEnabled", "FishHpThreshold", "QuickCatchSkill", "OpenerSkill",
    "OpenerMaxCount", "LoopSkills", "LoopStrictOrder", "EmergencyHealSkill",
    "EmergencyHealHp", "SkillEffectDelay", "SmartEffectAutoDetect"
}

local _smartComboSavePending = false
function ConfigModule.SaveSmartCombo()
    if not writefile or _smartComboSavePending then return end
    _smartComboSavePending = true
    task.delay(0.3, function()
        _smartComboSavePending = false
        local data = {}
        for _, k in ipairs(SMART_COMBO_KEYS) do
            data[k] = ConfigModule.Config[k]
        end
        local ok, encoded = pcall(function() return HttpService:JSONEncode(data) end)
        if ok and encoded then
            pcall(writefile, SMART_COMBO_FILE, encoded)
        end
    end)
end

function ConfigModule.LoadSmartComboAndSyncUI(uiControllers, onSyncLoopSkills)
    if not (isfile and isfile(SMART_COMBO_FILE) and readfile) then return end
    local ok, content = pcall(readfile, SMART_COMBO_FILE)
    if not ok or not content or #content == 0 then return end
    local decOk, data = pcall(function() return HttpService:JSONDecode(content) end)
    if not decOk or type(data) ~= "table" then return end

    for _, k in ipairs(SMART_COMBO_KEYS) do
        if data[k] ~= nil then
            ConfigModule.Config[k] = data[k]
        end
    end

    task.spawn(function()
        task.wait(0.1)
        for _, k in ipairs(SMART_COMBO_KEYS) do
            if uiControllers and uiControllers[k] and uiControllers[k].Set and ConfigModule.Config[k] ~= nil then
                pcall(function() uiControllers[k].Set(ConfigModule.Config[k], true) end)
            end
        end
        if onSyncLoopSkills and ConfigModule.Config.LoopSkills then
            pcall(onSyncLoopSkills, ConfigModule.Config.LoopSkills)
        end
    end)
end

-- 5. Boss Targets Persistence (HeavyweightFishing_BossTargets.json)
local BOSS_TARGETS_FILE = "HeavyweightFishing_BossTargets.json"
local _bossTargetsSavePending = false

function ConfigModule.SaveBossTargets()
    if not writefile or _bossTargetsSavePending then return end
    _bossTargetsSavePending = true
    task.delay(0.3, function()
        _bossTargetsSavePending = false
        local data = {}
        for k, v in pairs(ConfigModule.Config.SecretBossTargets) do
            data[k] = v
        end
        local ok, encoded = pcall(function() return HttpService:JSONEncode(data) end)
        if ok and encoded then
            pcall(writefile, BOSS_TARGETS_FILE, encoded)
        end
    end)
end

function ConfigModule.LoadBossTargetsAndSyncUI(bossTogglesMap)
    if not (isfile and isfile(BOSS_TARGETS_FILE) and readfile) then return end
    local ok, content = pcall(readfile, BOSS_TARGETS_FILE)
    if not ok or not content or #content == 0 then return end
    local decOk, data = pcall(function() return HttpService:JSONDecode(content) end)
    if not decOk or type(data) ~= "table" then return end

    for k, v in pairs(data) do
        if ConfigModule.Config.SecretBossTargets[k] ~= nil then
            ConfigModule.Config.SecretBossTargets[k] = v
        end
    end

    task.spawn(function()
        task.wait(0.1)
        if bossTogglesMap then
            for bName, val in pairs(ConfigModule.Config.SecretBossTargets) do
                if bossTogglesMap[bName] and bossTogglesMap[bName].Set then
                    pcall(function() bossTogglesMap[bName].Set(val, true) end)
                end
            end
        end
    end)
end

return ConfigModule

end

__modules["core.services"] = function()
--[[
    v2/core/services.lua
    Roblox Services, Player References & Cleanup Logic
--]]

local Services = {}

-- 1. Bind Roblox Services
Services.Players = game:GetService("Players")
Services.Workspace = game:GetService("Workspace")
Services.ReplicatedStorage = game:GetService("ReplicatedStorage")
Services.RunService = game:GetService("RunService")
Services.UserInputService = game:GetService("UserInputService")
Services.TweenService = game:GetService("TweenService")
Services.HttpService = game:GetService("HttpService")
Services.TeleportService = game:GetService("TeleportService")
Services.Lighting = game:GetService("Lighting")
Services.CoreGui = game:GetService("CoreGui")
Services.GuiService = game:GetService("GuiService")
Services.VirtualInputManager = pcall(function() return game:GetService("VirtualInputManager") end) and game:GetService("VirtualInputManager") or nil

-- 2. Player & Camera
Services.LocalPlayer = Services.Players.LocalPlayer
if not Services.LocalPlayer then
    Services.Players:GetPropertyChangedSignal("LocalPlayer"):Wait()
    Services.LocalPlayer = Services.Players.LocalPlayer
end
Services.Camera = Services.Workspace.CurrentCamera

-- 3. Safe Events folder lookup
Services.Events = Services.ReplicatedStorage:FindFirstChild("Events")
if not Services.Events then
    task.spawn(function()
        Services.Events = Services.ReplicatedStorage:WaitForChild("Events", 5)
    end)
end

-- 4. Clean old script instances
function Services.CleanOldInstances()
    pcall(function()
        local function purge(parent, name)
            if not parent then return end
            for _, c in ipairs(parent:GetChildren()) do
                if c.Name == name or c.Name:find("Identical") or c.Name:find("HeavyweightFishing") then
                    pcall(function() c:Destroy() end)
                end
            end
        end

        local gh = (gethui and gethui()) or nil
        if gh then
            purge(gh, "IdenticalHeavyweightFishing")
            purge(gh, "FloatingAvatar")
            purge(gh, "FloatingCrescent")
            purge(gh, "Notifications")
        end

        if Services.CoreGui then
            purge(Services.CoreGui, "IdenticalHeavyweightFishing")
            purge(Services.CoreGui, "FloatingAvatar")
            purge(Services.CoreGui, "FloatingCrescent")
            purge(Services.CoreGui, "Notifications")
        end

        local pGui = Services.LocalPlayer:FindFirstChild("PlayerGui")
        if pGui then
            purge(pGui, "IdenticalHeavyweightFishing")
            purge(pGui, "FloatingAvatar")
            purge(pGui, "FloatingCrescent")
            purge(pGui, "Notifications")
        end

        local espFolder = Services.Workspace:FindFirstChild("IdenticalESP")
        if espFolder then
            pcall(function() espFolder:Destroy() end)
        end
    end)
end

-- 5. Safe GUI Parent Resolver
function Services.GetGuiParent()
    local success, result = pcall(function()
        if gethui then return gethui() end
        if Services.CoreGui then return Services.CoreGui end
        return Services.LocalPlayer:WaitForChild("PlayerGui")
    end)
    return success and result or Services.LocalPlayer:WaitForChild("PlayerGui")
end

return Services

end

__modules["core.state"] = function()
--[[
    v2/core/state.lua
    Shared Runtime State, Active Connections, Mutexes & Priority Manager
--]]

local State = {}

-- 1. Lifecycle Flags & Tracking
State.isRunning = true
State.activeConnections = {}
State.cleanUpInstances = {}
State.UIControllers = {}
State.ConfigLabelMap = {}
State.bossTogglesMap = {}

-- 2. Secret Boss Runtime State
State.secretBossState = {
    active = false,
    activeBoss = nil,
    currentIsland = nil,
    teleportedToBoss = false,
    isCatchingTarget = false,
    webhookSentForCurrent = false,
    lastHookedCheckTime = 0,
    lastHomeReturnTime = 0
}

-- 3. Ticket Quest Runtime State
State.ticketQuestState = {
    active = false,
    currentQuestType = "none",
    isCooldown = false,
    isBusyRoutine = false,
    isAtHomeSpot = false,
    lastScanTime = 0
}

-- 4. Gem Tracker
State.gemTracker = {
    baseline = 0,
    gained = 0,
    fishCount = 0
}

-- 5. Combo State
State.comboState = {
    openerUsedCount = 0,
    openerDone = false,
    loopTargetIndex = 1,
    loopIndex = 1,
    lastCastTime = 0,
    lastActionTime = 0,
    minigameStartTime = 0,
    usedTimes = { Z = 0, X = 0, C = 0, V = 0 },
    defaultCooldowns = { Z = 2.5, X = 3.0, C = 5.0, V = 4.0 },
    loopWaitStartTime = 0
}

-- 6. Priority Manager
State.PriorityManager = {
    cachedTask = "NormalFarm",
    lastTaskScan = 0
}

function State.PriorityManager.GetTaskDisplayName(taskKey)
    if taskKey == "SecretBoss" then return "🎯 Săn Secret Boss"
    elseif taskKey == "TicketQuest" then return "📜 Làm Vé Nhiệm Vụ"
    elseif taskKey == "GodSpirit" then return "⛩️ Cúng Thần Linh"
    elseif taskKey == "TrainSkill" then return "⚔️ Auto Luyện Chiêu"
    else return "🎣 Treo Farm Thường" end
end

function State.AddConnection(conn)
    if conn then table.insert(State.activeConnections, conn) end
    return conn
end

function State.AddInstance(inst)
    if inst then table.insert(State.cleanUpInstances, inst) end
    return inst
end

function State.UnloadScript(onCustomUnload)
    if not State.isRunning then return end
    State.isRunning = false

    for _, conn in ipairs(State.activeConnections) do
        pcall(function()
            if typeof(conn) == "RBXScriptConnection" and conn.Connected then
                conn:Disconnect()
            end
        end)
    end
    table.clear(State.activeConnections)

    if onCustomUnload then pcall(onCustomUnload) end

    for _, inst in ipairs(State.cleanUpInstances) do
        pcall(function()
            if typeof(inst) == "Instance" and inst.Parent then
                inst:Destroy()
            end
        end)
    end
    table.clear(State.cleanUpInstances)

    local gEnv = (getgenv and getgenv()) or _G or shared
    if gEnv then
        gEnv.HeavyweightFishingKill = nil
        gEnv.IdenticalHeavyweightFishingUnload = nil
    end
end

return State

end

__modules["core.utils"] = function()
--[[
    v2/core/utils.lua
    Notification System, Health Calculation & Number Formatting Utilities
--]]

local Services = __require("core.services")
local Workspace = Services.Workspace
local LocalPlayer = Services.LocalPlayer
local HttpService = Services.HttpService
local TweenService = Services.TweenService

local Utils = {}

-- 1. Number Formatting
function Utils.FormatWithSpaces(val)
    local num = tonumber(val)
    if not num then return tostring(val or "") end
    local formatted = tostring(math.floor(num))
    local k
    while true do
        formatted, k = string.gsub(formatted, "^(-?%d+)(%d%d%d)", "%1 %2")
        if k == 0 then break end
    end
    return formatted
end

function Utils.FormatNumber(val)
    local n = tonumber(val)
    if not n then return "0" end
    if n >= 1e9 then
        return string.format("%.2fB", n / 1e9)
    elseif n >= 1e6 then
        return string.format("%.2fM", n / 1e6)
    elseif n >= 1e3 then
        return string.format("%.1fK", n / 1e3)
    end
    return tostring(math.floor(n))
end

-- 2. Notification System (StarterGui + In-game Floating Toast)
local notifContainer = nil
function Utils.SetNotifContainer(container)
    notifContainer = container
end

function Utils.ShowNotification(title, text, notifType, duration)
    duration = duration or 3
    -- Fallback to StarterGui
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = title or "Thông Báo",
            Text = text or "",
            Duration = duration
        })
    end)

    -- Floating toast if UI container is available
    if notifContainer and notifContainer.Parent then
        pcall(function()
            local toast = Instance.new("Frame")
            toast.Size = UDim2.new(1, 0, 0, 48)
            toast.BackgroundColor3 = Color3.fromRGB(22, 24, 30)
            toast.BorderSizePixel = 0
            toast.BackgroundTransparency = 0.1

            local uic = Instance.new("UICorner")
            uic.CornerRadius = UDim.new(0, 8)
            uic.Parent = toast

            local uis = Instance.new("UIStroke")
            uis.Color = (notifType == "SUCCESS" and Color3.fromRGB(46, 204, 113))
                or (notifType == "WARN" and Color3.fromRGB(230, 126, 34))
                or (notifType == "ERROR" and Color3.fromRGB(231, 76, 60))
                or Color3.fromRGB(0, 168, 255)
            uis.Thickness = 1.2
            uis.Parent = toast

            local tTitle = Instance.new("TextLabel")
            tTitle.Text = title or "Identical Hub"
            tTitle.TextColor3 = uis.Color
            tTitle.Font = Enum.Font.GothamBold
            tTitle.TextSize = 13
            tTitle.Position = UDim2.new(0, 12, 0, 6)
            tTitle.Size = UDim2.new(1, -24, 0, 16)
            tTitle.BackgroundTransparency = 1
            tTitle.TextXAlignment = Enum.TextXAlignment.Left
            tTitle.Parent = toast

            local tDesc = Instance.new("TextLabel")
            tDesc.Text = text or ""
            tDesc.TextColor3 = Color3.fromRGB(200, 205, 215)
            tDesc.Font = Enum.Font.Gotham
            tDesc.TextSize = 12
            tDesc.Position = UDim2.new(0, 12, 0, 24)
            tDesc.Size = UDim2.new(1, -24, 0, 18)
            tDesc.BackgroundTransparency = 1
            tDesc.TextXAlignment = Enum.TextXAlignment.Left
            tDesc.TextTruncate = Enum.TextTruncate.AtEnd
            tDesc.Parent = toast

            toast.Parent = notifContainer
            task.delay(duration, function()
                if toast and toast.Parent then
                    local tw = TweenService:Create(toast, TweenInfo.new(0.3), { BackgroundTransparency = 1 })
                    tw:Play()
                    tw.Completed:Wait()
                    toast:Destroy()
                end
            end)
        end)
    end
end

-- 3. Health Calculation
function Utils.GetFishHealth(fUI)
    -- 1. Check Workspace.Fishes
    local fishID = LocalPlayer:GetAttribute("FishID")
    if fishID and Workspace:FindFirstChild("Fishes") then
        local f = Workspace.Fishes:FindFirstChild(fishID)
        if f then
            local hpVal = f:FindFirstChild("FishHealth") or f:FindFirstChild("Health")
            if hpVal and (hpVal:IsA("NumberValue") or hpVal:IsA("IntValue")) and hpVal.Value > 0 then
                return hpVal.Value
            end
        end
    end

    -- 2. Check Character attributes
    local char = LocalPlayer.Character
    if char then
        for _, att in ipairs({"FishHealth", "FishHP", "TargetHealth", "BossHP", "TargetHP"}) do
            local val = char:GetAttribute(att)
            if val and tonumber(val) and tonumber(val) > 0 then
                return tonumber(val)
            end
        end
    end

    -- 3. Check fUI (Fishing GUI)
    if fUI then
        local bossBar = fUI:FindFirstChild("BossFightBar")
        if bossBar and bossBar.Visible and bossBar.Size.X.Scale > 0 then
            return 999999 -- Boss đang chiến đấu
        end

        for _, d in ipairs(fUI:GetDescendants()) do
            if d:IsA("TextLabel") and d.Visible and d.Text ~= "" then
                local dName = d.Name:lower()
                if (dName:find("fish") or dName:find("boss") or dName:find("enemy")) and not dName:find("player") then
                    local kMatch = d.Text:match("([%d%.]+)%s*[kK]")
                    if kMatch and tonumber(kMatch) then return tonumber(kMatch) * 1000 end
                    local slashMatch = d.Text:match("([%d,%.]+)%s*/")
                    if slashMatch then
                        local n = tonumber(slashMatch:gsub("[,]", ""))
                        if n and n > 0 then return n end
                    end
                end
            end
        end
    end

    return 10 -- Cá thông thường mặc định
end

function Utils.GetPlayerHealth(fUI)
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum and hum.MaxHealth > 0 then
        return (hum.Health / hum.MaxHealth) * 100
    end

    if fUI and fUI:FindFirstChild("HPPlayer") then
        local hpP = fUI.HPPlayer
        local pBar = hpP:FindFirstChild("ProgressionBar")
        if pBar and pBar:FindFirstChild("Bar") then
            return pBar.Bar.Size.X.Scale * 100
        end
    end

    return 100
end

-- 4. Discord Webhook Sender
function Utils.SendDiscordWebhook(title, description, color, fields, webhookUrl)
    if not webhookUrl or webhookUrl == "" or not webhookUrl:find("discord%.com/api/webhooks") then
        return
    end

    local payload = {
        embeds = {
            {
                title = title or "Heavyweight Fishing Notification",
                description = description or "",
                color = color or 3447003,
                fields = fields or {},
                footer = { text = "Identical Hub • Heavyweight Fishing V2" },
                timestamp = DateTime.now():ToIsoDate()
            }
        }
    }

    local req = (syn and syn.request) or (http and http.request) or http_request or (fluxus and fluxus.request) or request
    if req then
        task.spawn(function()
            pcall(req, {
                Url = webhookUrl,
                Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode(payload)
            })
        end)
    end
end

-- 5. Telegram Bot Sender
function Utils.SendTelegramMessage(token, chatId, text)
    if not token or token == "" or not chatId or chatId == "" or not text or text == "" then return end
    pcall(function()
        local url = "https://api.telegram.org/bot" .. token .. "/sendMessage"
        local payload = {
            chat_id = chatId,
            text = text,
            parse_mode = "Markdown"
        }
        local body = HttpService:JSONEncode(payload)
        local headers = { ["Content-Type"] = "application/json" }
        local req = (syn and syn.request) or (http and http.request) or http_request or (fluxus and fluxus.request) or request
        if req then
            task.spawn(function()
                pcall(req, {
                    Url = url,
                    Method = "POST",
                    Headers = headers,
                    Body = body
                })
            end)
        end
    end)
end

-- 6. NPC Detection Alert (Discord + Telegram with Anti-Spam)
local npcAlertsSent = {}
function Utils.SendNPCDetectionAlert(npcType, npcName, npcInst, config)
    if not config then return end
    local alertKey = tostring(game.JobId or "local") .. "_" .. tostring(npcType)
    if npcAlertsSent[alertKey] then return end
    npcAlertsSent[alertKey] = true

    local posStr = "Không xác định"
    if npcInst then
        local root = npcInst:FindFirstChild("HumanoidRootPart") or npcInst.PrimaryPart or npcInst:FindFirstChild("Head") or npcInst:FindFirstChildWhichIsA("BasePart")
        if root then
            local p = root.Position
            posStr = string.format("X: %.1f, Y: %.1f, Z: %.1f", p.X, p.Y, p.Z)
        end
    end

    local jobId = tostring(game.JobId or "")
    local placeId = tostring(game.PlaceId or "0")
    local playerName = (LocalPlayer and LocalPlayer.Name) or "Unknown"
    local timeStr = os.date("%H:%M:%S - %d/%m/%Y")

    -- Discord Webhook
    if config.WebhookEnabled and config.WebhookNotifyNPC and config.WebhookUrl and #config.WebhookUrl > 0 then
        local fields = {
            { name = "🎯 NPC Phát Hiện", value = "**" .. tostring(npcName) .. "**", inline = true },
            { name = "👤 Người Tìm Thấy", value = playerName, inline = true },
            { name = "📍 Tọa Độ Đứng", value = posStr, inline = true },
            { name = "🔑 Job ID Server", value = "```" .. (jobId ~= "" and jobId or "N/A (Chơi 1 mình)") .. "```", inline = false },
            { name = "⚡ Lệnh Vào Server Nhanh", value = "```lua\ngame:GetService(\"TeleportService\"):TeleportToPlaceInstance(" .. placeId .. ", \"" .. jobId .. "\", game.Players.LocalPlayer)\n```", inline = false },
            { name = "⏰ Thời Gian", value = timeStr, inline = true }
        }
        Utils.SendDiscordWebhook("📜 PHÁT HIỆN " .. tostring(npcName):upper() .. " TRONG SERVER!", "Bot đã tìm thấy **" .. tostring(npcName) .. "** tại server hiện tại!", 16753920, fields, config.WebhookUrl)
    end

    -- Telegram Bot
    if config.TelegramEnabled and config.TelegramNotifyNPC and config.TelegramBotToken and #config.TelegramBotToken > 0 and config.TelegramChatId and #config.TelegramChatId > 0 then
        local teleText = "📜 *PHÁT HIỆN " .. tostring(npcName):upper() .. "!*\n\n"
            .. "🎯 *NPC:* " .. tostring(npcName) .. "\n"
            .. "👤 *Người tìm thấy:* " .. playerName .. "\n"
            .. "📍 *Tọa độ:* " .. posStr .. "\n"
            .. "🔑 *Job ID:* `" .. (jobId ~= "" and jobId or "N/A") .. "`\n"
            .. "⏰ *Thời gian:* " .. timeStr .. "\n\n"
            .. "⚡ *Code vào server:*\n`game:GetService(\"TeleportService\"):TeleportToPlaceInstance(" .. placeId .. ", \"" .. jobId .. "\", game.Players.LocalPlayer)`"
        Utils.SendTelegramMessage(config.TelegramBotToken, config.TelegramChatId, teleText)
    end
end

-- 7. Queue Script On Teleport & ServerHop
function Utils.QueueScriptOnTeleport()
    local qot = queue_on_teleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
    if qot then
        pcall(function()
            qot([[loadstring(game:HttpGet("https://raw.githubusercontent.com/VNGteam/Heavyweight-Fishing/main/loader_v2.lua"))()]])
        end)
    end
end

function Utils.ServerHop(avoidServers)
    Utils.ShowNotification("Đổi Server", "Đang tìm kiếm server phù hợp...", "WARN")
    Utils.QueueScriptOnTeleport()
    task.spawn(function()
        local placeId = game.PlaceId
        local avoidMap = {}
        if avoidServers and type(avoidServers) == "table" then
            for _, sid in ipairs(avoidServers) do avoidMap[sid] = true end
        end
        avoidMap[game.JobId] = true

        local cursor = ""
        local candidates = {}
        for page = 1, 4 do
            local url = string.format("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100%s", placeId, cursor ~= "" and ("&cursor=" .. cursor) or "")
            local ok, res = pcall(function() return game:HttpGet(url) end)
            if ok and res then
                local bOk, body = pcall(function() return HttpService:JSONDecode(res) end)
                if bOk and body and body.data then
                    for _, s in ipairs(body.data) do
                        if s.playing and s.maxPlayers and s.id and not avoidMap[s.id] then
                            local free = s.maxPlayers - s.playing
                            if free >= 2 then
                                table.insert(candidates, s.id)
                            end
                        end
                    end
                    if #candidates >= 5 then break end
                    cursor = body.nextPageCursor or ""
                    if not cursor or cursor == "" then break end
                end
            end
            task.wait(0.15)
        end

        local TeleportService = Services.TeleportService
        local chosen = (#candidates > 0 and candidates[math.random(1, #candidates)]) or nil
        if chosen then
            Utils.ShowNotification("Đổi Server", "Đã tìm thấy server mới! Đang chuyển...", "SUCCESS", 3)
            task.wait(0.5)
            local ok, err = pcall(function() TeleportService:TeleportToPlaceInstance(placeId, chosen, LocalPlayer) end)
            if not ok then
                pcall(function() TeleportService:Teleport(placeId, LocalPlayer) end)
            end
            return
        end
        Utils.ShowNotification("Đổi Server", "Đang chuyển sang server ngẫu nhiên...", "INFO", 3)
        task.wait(0.5)
        pcall(function() TeleportService:Teleport(placeId, LocalPlayer) end)
    end)
end

return Utils

end

__modules["features.boss"] = function()
--[[
    v2/features/boss.lua
    Secret Boss Hunting, Fast Skip, Spot Allocation, Teleportation & Chat Sniper
--]]

local Services = __require("core.services")
local Events = Services.Events
local LocalPlayer = Services.LocalPlayer
local Workspace = Services.Workspace
local HttpService = Services.HttpService
local Utils = __require("core.utils")

local Boss = {}

-- 1. Database of Secret Bosses & Islands
Boss.database = {
    ["Coral Island"] = {
        islandName = "Coral Island",
        weather = "None",
        patterns = {"coral", "san ho"},
        reqPower = 100,
        pos = Vector3.new(-120, 15, -450),
        bosses = { "Coral Guardian", "Radiant Sunfish" }
    },
    ["Glacier Island"] = {
        islandName = "Glacier Island",
        weather = "Snow",
        patterns = {"glacier", "ice", "bang tuyet"},
        reqPower = 500,
        pos = Vector3.new(650, 20, -1200),
        bosses = { "Glacier Leviathan", "Armored Shark", "Frost Kingfish", "Frost Queenfish" }
    },
    ["Volcano Island"] = {
        islandName = "Volcano Island",
        weather = "None",
        patterns = {"volcano", "nui lua", "lava", "magma"},
        reqPower = 1000,
        pos = Vector3.new(-1400, 25, 800),
        bosses = { "Lava Serpent", "Magma Behemoth", "Volcanic Shark", "Reborn Puffer Beast" }
    },
    ["Deep Ocean"] = {
        islandName = "Deep Ocean",
        weather = "Storm",
        patterns = {"ocean", "deep", "kraken"},
        reqPower = 1500,
        pos = Vector3.new(2000, 10, 2000),
        bosses = { "Kraken", "Corrupted Kraken", "Phantom Kraken", "Ancient Megalodon", "Megalodon", "Heaven Piercer Turtle" }
    },
    ["Abyssal Trench"] = {
        islandName = "Abyssal Trench",
        weather = "None",
        patterns = {"abyss", "vuc tham", "depth"},
        reqPower = 2500,
        pos = Vector3.new(-2500, 5, -3000),
        bosses = { "Abyssal Behemoth", "Ancient Depth Serpent", "Void Serpent", "Abyss Dweller", "Mountain Dragonwhale", "Mirage Lanternfish", "Nameless Octoparasite" }
    }
}

-- Lookup table: Boss Name -> Island info
Boss.lookup = {}
for islandName, info in pairs(Boss.database) do
    for _, bossName in ipairs(info.bosses) do
        Boss.lookup[bossName] = info
    end
end

Boss.activeBoss = nil
Boss.isCatchingTarget = false
Boss.lastHookedCheckTime = 0
Boss.webhookSentForCurrent = false
Boss.customSpots = {}

-- 2. Quản lý Slot Điểm Câu An Toàn Theo Acc & Jitter
function Boss.GetAllocatedSlot(config)
    if config.BossSpotAllocationMode == "Tự Động (Theo Acc)" then
        local uid = LocalPlayer.UserId or 12345
        return (uid % 5) + 1
    else
        return tonumber(config.SelectedCustomSpotSlot) or 1
    end
end

function Boss.ApplyJitter(pos, config)
    if not config.BossTeleportJitter or not pos then return pos end
    local dist = tonumber(config.BossTeleportJitterDist) or 1.0
    local rx = (math.random() - 0.5) * 2 * dist
    local rz = (math.random() - 0.5) * 2 * dist
    return pos + Vector3.new(rx, 0, rz)
end

function Boss.LoadCustomSpots()
    if not (isfile and readfile and isfile("HeavyweightFishing_CustomSpots.json")) then return end
    pcall(function()
        local raw = readfile("HeavyweightFishing_CustomSpots.json")
        local dec = HttpService:JSONDecode(raw)
        if dec and type(dec) == "table" then
            Boss.customSpots = dec
        end
    end)
end

function Boss.SaveCustomSpots()
    if not (writefile and HttpService) then return end
    pcall(function()
        writefile("HeavyweightFishing_CustomSpots.json", HttpService:JSONEncode(Boss.customSpots))
    end)
end

function Boss.SetCustomSpot(island, slot, pos)
    if not Boss.customSpots[island] then Boss.customSpots[island] = {} end
    Boss.customSpots[island][tostring(slot)] = { x = pos.X, y = pos.Y, z = pos.Z }
    Boss.SaveCustomSpots()
end

function Boss.GetCustomSpot(island, slot)
    if Boss.customSpots[island] and Boss.customSpots[island][tostring(slot)] then
        local p = Boss.customSpots[island][tostring(slot)]
        return Vector3.new(p.x, p.y, p.z)
    end
    return nil
end

-- 3. Detect Currently Hooked Fish Name
function Boss.GetCurrentHookedFishName(fUI)
    local char = LocalPlayer.Character
    if char then
        local fishName = char:GetAttribute("HookedFish") or char:GetAttribute("FishName") or char:GetAttribute("TargetFish")
        if fishName and tostring(fishName) ~= "" then
            return tostring(fishName)
        end
    end

    if fUI then
        for _, d in ipairs(fUI:GetDescendants()) do
            if d:IsA("TextLabel") and d.Visible and d.Text ~= "" then
                local txt = d.Text
                for bossName in pairs(Boss.lookup) do
                    if txt:lower():find(bossName:lower(), 1, true) then
                        return bossName
                    end
                end
            end
        end
    end

    return "Unknown"
end

-- 4. Fast-Skip Non-Target Fish
function Boss.HandleFastSkip(config, fUI, isMinigame)
    if not isMinigame or not config.FastSkipNonTarget then return end
    local now = tick()
    if (now - Boss.lastHookedCheckTime < 0.2) then return end
    Boss.lastHookedCheckTime = now

    local hookedName = Boss.GetCurrentHookedFishName(fUI)
    if hookedName and hookedName ~= "Unknown" then
        local isTarget = false
        if config.SecretBossTargets and config.SecretBossTargets[hookedName] == true then
            isTarget = true
        end

        if isTarget then
            Boss.isCatchingTarget = true
            if config.SecretBossAlertWebhook and not Boss.webhookSentForCurrent then
                Boss.webhookSentForCurrent = true
                if config.WebhookUrl ~= "" then
                    Utils.SendDiscordWebhook(
                        "🔥 ĐÃ CẮN CÂU SECRET BOSS!",
                        string.format("Người chơi **%s** vừa móc câu thành công Boss: **%s**!", LocalPlayer.Name, hookedName),
                        16711680,
                        {
                            { name = "Boss Name", value = hookedName, inline = true },
                            { name = "Tọa Độ", value = tostring(LocalPlayer.Character and LocalPlayer.Character:GetPivot().Position or "N/A"), inline = true }
                        },
                        config.WebhookUrl
                    )
                end
                if config.TelegramNotifyBoss and config.TelegramBotToken ~= "" and config.TelegramChatId ~= "" then
                    Utils.SendTelegramMessage(
                        config,
                        string.format("🔥 *ĐÃ CẮN CÂU SECRET BOSS!*\\nNgười chơi: `%s`\\nBoss: *%s*", LocalPlayer.Name, hookedName)
                    )
                end
            end
        else
            Boss.isCatchingTarget = false
            pcall(function()
                if Events and Events:FindFirstChild("CancelCast") then
                    Events.CancelCast:FireServer()
                end
            end)
        end
    end
end

-- 5. Chat Sniper & Teleport
function Boss.HandleChatMessage(message, config)
    if not config.AutoChatSecretBoss or not message or message == "" then return end
    local lowerMsg = message:lower()

    if lowerMsg:find("caught") or lowerMsg:find("has caught") or lowerMsg:find("câu được") or lowerMsg:find("bắt được") then
        return
    end

    for bossName, islandData in pairs(Boss.lookup) do
        if lowerMsg:find(bossName:lower(), 1, true) then
            Utils.ShowNotification("Săn Boss Bí Mật", "Phát hiện Boss [" .. bossName .. "] xuất hiện! Đang di chuyển...", "WARN", 5)
            Boss.activeBoss = bossName

            local slot = Boss.GetAllocatedSlot(config)
            local customPos = Boss.GetCustomSpot(islandData.islandName, slot)
            local targetPos = customPos or islandData.pos

            if targetPos then
                targetPos = Boss.ApplyJitter(targetPos, config)
                local char = LocalPlayer.Character
                local root = char and char:FindFirstChild("HumanoidRootPart")
                if root then
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.CFrame = CFrame.new(targetPos + Vector3.new(0, 5, 0))
                end
            end
            break
        end
    end
end

pcall(Boss.LoadCustomSpots)

return Boss

end

__modules["features.boss_dps"] = function()
--[[
    v2/features/boss_dps.lua
    Multiplayer Boss DPS & Damage Percentage Meter HUD (Multi-Phase Support)
--]]

local Services = __require("core.services")
local Players = Services.Players
local Workspace = Services.Workspace
local LocalPlayer = Services.LocalPlayer
local Events = Services.Events
local State = __require("core.state")
local Utils = __require("core.utils")
local Theme = __require("ui.theme")

local BossDps = {}

local tracker = {
    active = false,
    currentFish = nil,
    fishId = "",
    bossName = "Secret Boss",
    currentPhase = 1,
    phaseMaxHp = 0,
    totalBossMaxHp = 0,
    curHp = 0,
    lastHp = 0,
    totalDamage = 0,
    players = {},
    victoryUntil = 0,
    phaseTransitionUntil = 0
}

local recentPlayerAction = {}

local function IsPlayerAttacking(pName, char)
    if not char then return false end
    if pName == LocalPlayer.Name then
        local act = recentPlayerAction[pName]
        if act and (tick() - act) <= 0.45 then
            return true
        end
    end
    for _, att in ipairs({"UsingSkill", "SkillActive", "IsAttacking", "CastingSkill", "SkillLocked"}) do
        local val = char:GetAttribute(att)
        if val == true or (typeof(val) == "number" and val > 0) then
            return true
        end
    end
    local skillsFolder = char:FindFirstChild("Skills")
    if skillsFolder then
        for _, sk in ipairs(skillsFolder:GetChildren()) do
            local usk = sk:GetAttribute("UsingSkill")
            if usk and tonumber(usk) and tonumber(usk) > 0 then
                return true
            end
        end
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local anim = hum and hum:FindFirstChildOfClass("Animator")
    if anim then
        local ok, tracks = pcall(function() return anim:GetPlayingAnimationTracks() end)
        if ok and tracks then
            for _, tr in ipairs(tracks) do
                if tr.IsPlaying and tr.Priority.Value >= Enum.AnimationPriority.Action.Value then
                    local name = tr.Name:lower()
                    if not name:find("fish") and not name:find("rod") and not name:find("reel") and not name:find("idle") and not name:find("walk") and not name:find("run") then
                        return true
                    end
                end
            end
        end
    end
    local lastAct = recentPlayerAction[pName]
    if lastAct and (tick() - lastAct) <= 0.45 then
        return true
    end
    return false
end

pcall(function()
    if Events and Events:FindFirstChild("UseSkill") then
        local oldUse = Events.UseSkill.FireServer
        Events.UseSkill.FireServer = function(self, ...)
            recentPlayerAction[LocalPlayer.Name] = tick()
            return oldUse(self, ...)
        end
    end
    if Events and Events:FindFirstChild("Slam") then
        local oldSlam = Events.Slam.FireServer
        Events.Slam.FireServer = function(self, ...)
            recentPlayerAction[LocalPlayer.Name] = tick()
            return oldSlam(self, ...)
        end
    end
end)

local widget = nil
local dpsTitle = nil
local dpsBossHpLabel = nil
local dpsHpBarFill = nil
local dpsListContainer = nil
