                savedAt = os.date("%H:%M:%S")
            }
            infoHomeSpot.Set(string.format("Đã lưu: X:%.1f, Y:%.1f, Z:%.1f (%s)", root.Position.X, root.Position.Y, root.Position.Z, Config.HomeFarmSpot.savedAt))
