    local btnContainer = Instance.new("Frame")
    btnContainer.Size = UDim2.new(0, 190, 0, 24)
    btnContainer.Position = UDim2.new(1, -190, 0.5, -12)
    btnContainer.BackgroundTransparency = 1
    btnContainer.Parent = quickRow

