    local miscCard = Components.CreateCardGroup(parent)

    Components.CreateToggleRow(miscCard, "Tự Động Bán Cá Khi Đầy Túi", "Tự động bán cá theo chu kỳ", Config.AutoSell, function(v) Config.AutoSell = v end)
    Components.CreateSliderRow(miscCard, "Giãn Cách Bán Cá Tự Động", "Khoảng thời gian giữa 2 lần bán", 10, 120, Config.SellInterval, false, "s", function(v) Config.SellInterval = v end)
    Components.CreateToggleRow(miscCard, "Tự Đánh Nhịp Octo (Rhythm Hit)", "Tự hoàn thành minigame nhịp điệu của bạch tuộc", Config.OctoAutoMinigame, function(v) Config.OctoAutoMinigame = v end)
end

return TabCauCa

end

__modules["ui.tabs.tab_dich_chuyen"] = function()
--[[
    v2/ui/tabs/tab_dich_chuyen.lua
    Full Teleport System: 10 Islands, Boss Realms, Secret Rods, Rod Dealers, Players & 17 Quest NPCs
--]]

local Components = __require("ui.components")
local Teleport = __require("features.teleport")
local Services = __require("core.services")
local Spirits = __require("features.spirits")
local Utils = __require("core.utils")

local Players = Services.Players
local LocalPlayer = Services.LocalPlayer
local Workspace = Services.Workspace

local TabDichChuyen = {}

local WorldData = {
    islands = {
        {name = "[1] Đảo Khởi Đầu (Spawn)", pos = Vector3.new(-200.7, 11.1, 35.9), radius = 850},
        {name = "[2] Đảo Tre (Bamboo Isle)", pos = Vector3.new(-1223.0, 7.3, -24.1), radius = 850},
        {name = "[3] Đảo Phóng Xạ (Fallout Isle)", pos = Vector3.new(65.5, 8.8, 1181.3), radius = 850},
        {name = "[4] Đảo Thống Trị (Sovereign Isle)", pos = Vector3.new(-1276.4, 8.8, 1239.7), radius = 850},
        {name = "[5] Đảo Cá Chép (Perch Isle)", pos = Vector3.new(-62.0, 11.9, -1321.4), radius = 850},
        {name = "[6] Đảo Băng Giá (Frost Isle)", pos = Vector3.new(-1366.0, 11.9, -1495.4), radius = 850},
        {name = "[7] Đảo Quả Dừa (Coconut Isle)", pos = Vector3.new(1493.6, 9.1, -1430.6), radius = 850},
        {name = "[8] Đảo Hổ Phách (Amber Isle)", pos = Vector3.new(1259.4, 9.1, 1401.5), radius = 850},
        {name = "[9] Đảo Chiến Trường (Battlefield)", pos = Vector3.new(1393.5, 11.3, 169.6), radius = 850},
        {name = "[10] Đảo Đỉnh Sương Mù (Mistpeak)", pos = Vector3.new(2660.2, 8.8, -86.7), radius = 850},
    },
    bossRealms = {
        {name = "Boss Bạch Tuộc (Phao Biển)", pos = Vector3.new(1608.2, 5.0, -218.3), radius = 450},
        {name = "Vùng Câu Cá Ngầm Lòng Đất", pos = Vector3.new(112.5, -330.0, -30.8), radius = 450},
        {name = "Đấu Trường Boss Enzo", pos = Vector3.new(-115.3, 9.2, 1349.5), radius = 450},
    }
}

local function GetCurrentLocationName()
    local char = LocalPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return "Đang tải vị trí...", nil end
    local myPos = root.Position

    if myPos.Y < -150 then
        return "Vùng Câu Cá Ngầm Lòng Đất", "underground"
    end

    local bestName = "Đang ở giữa biển"
    local bestObj = nil
    local minDist = 999999

    for _, isl in ipairs(WorldData.islands) do
        local dist = (Vector3.new(myPos.X, 0, myPos.Z) - Vector3.new(isl.pos.X, 0, isl.pos.Z)).Magnitude
        if dist < (isl.radius or 850) and dist < minDist then
            minDist = dist
            bestName = isl.name
            bestObj = isl
        end
    end

    for _, br in ipairs(WorldData.bossRealms) do
        local dist = (myPos - br.pos).Magnitude
        if dist < (br.radius or 450) and dist < minDist then
            minDist = dist
            bestName = br.name
            bestObj = br
        end
    end

    return bestName, bestObj, minDist
end

function TabDichChuyen.Render(parent)
    -- ============================================================
    -- 1. DỊCH CHUYỂN ĐẾN ĐẢO (1 - 10)
    -- ============================================================
    Components.CreateCategoryHeader(parent, "🏝️ Dịch Chuyển Đến Đảo (Đảo 1 - 10)")
    local islandCard = Components.CreateCardGroup(parent)

    local infoCurrentMap = Components.CreateInfoRow(islandCard, "📍 Vị Trí Bạn Đang Đứng", "Đang nhận diện...")

    Components.CreateButtonRow(islandCard, "📋 Sao Chép Tọa Độ Hiện Tại", "Copy tọa độ đứng hiện tại vào Clipboard để lưu trữ", "Sao Chép", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local pos = root.Position
        local str = string.format("Vector3.new(%.1f, %.1f, %.1f)", pos.X, pos.Y, pos.Z)
        pcall(function()
            if setclipboard then setclipboard(str)
            elseif toclipboard then toclipboard(str) end
        end)
        Utils.ShowNotification("TỌA ĐỘ HIỆN TẠI", "Đã copy: " .. str .. " vào Clipboard!", "SUCCESS", 5)
    end)

    task.spawn(function()
        while true do
            task.wait(2.0)
            if infoCurrentMap and infoCurrentMap.Set then
                local locName = GetCurrentLocationName()
                infoCurrentMap.Set(locName)
            end
        end
    end)

    for _, isl in ipairs(WorldData.islands) do
        Components.CreateButtonRow(islandCard, isl.name, "Bay thẳng đến " .. isl.name, "Bay Tới", function()
            local curLoc = GetCurrentLocationName()
            if curLoc == isl.name then
                Utils.ShowNotification("Dịch Chuyển", "Bạn đang ở ngay " .. isl.name .. " rồi!", "INFO", 3)
                return
            end
            Teleport.To(isl.pos + Vector3.new(0, 3, 0))
            Utils.ShowNotification("Dịch Chuyển", "Đã đến " .. isl.name .. "!", "SUCCESS", 3)
        end)
    end

    -- ============================================================
    -- 2. ĐẤU TRƯỜNG BOSS & VÙNG ĐẤT BÍ MẬT
    -- ============================================================
    Components.CreateCategoryHeader(parent, "🐙 Đấu Trường Boss & Vùng Đất Bí Mật")
    local bossRealmCard = Components.CreateCardGroup(parent)

    for _, br in ipairs(WorldData.bossRealms) do
        Components.CreateButtonRow(bossRealmCard, br.name, "Dịch chuyển tức thì đến " .. br.name, "Bay Đến", function()
            Teleport.To(br.pos + Vector3.new(0, 3, 0))
            Utils.ShowNotification("Dịch Chuyển", "Đã đến " .. br.name .. "!", "SUCCESS", 4)
        end)
    end

    -- ============================================================
    -- 3. CỬA HÀNG BÁN CẦN (BIAO DI)
    -- ============================================================
    Components.CreateCategoryHeader(parent, "🏪 Cửa Hàng Bán Cần (Biao Di)")
    local rodDealerCard = Components.CreateCollapsibleCardGroup(parent, "Danh Sách Thợ Bán Cần Tại Các Đảo", false)

    local rodDealers = {
        {name = "[1] Shop Đảo Khởi Đầu", pos = Vector3.new(-151.4, 8.7, -49.9)},
        {name = "[2] Shop Đảo Tre", pos = Vector3.new(-1236.8, 7.3, -174.1)},
        {name = "[3] Shop Đảo Phóng Xạ", pos = Vector3.new(138.4, 9.0, 1179.7)},
        {name = "[4] Shop Đảo Thống Trị", pos = Vector3.new(-1262.6, 8.2, 1202.2)},
        {name = "[5] Shop Đảo Cá Chép", pos = Vector3.new(-9.5, 9.2, -1330.0)},
        {name = "[6] Shop Đảo Băng Giá", pos = Vector3.new(-1400.4, 9.2, -1490.6)},
        {name = "[7] Shop Đảo Quả Dừa", pos = Vector3.new(1446.0, 9.3, -1408.0)},
        {name = "[8] Shop Đảo Hổ Phách", pos = Vector3.new(1292.7, 8.2, 1497.4)},
    }

    for _, rd in ipairs(rodDealers) do
        Components.CreateButtonRow(rodDealerCard, rd.name, "Bay trực tiếp đến " .. rd.name, "Bay Đến", function()
            Teleport.To(rd.pos + Vector3.new(0, 3, 0))
            Utils.ShowNotification("Cửa Hàng", "Đã đến " .. rd.name .. "!", "SUCCESS", 3)
        end)
    end

    -- ============================================================
    -- 4. VỊ TRÍ CẦN CÂU BÍ MẬT
    -- ============================================================
    Components.CreateCategoryHeader(parent, "✨ Vị Trí Cần Câu Bí Mật (Secret Rods)")
    local sRodCard = Components.CreateCardGroup(parent)

    local secretRods = {
        {name = "Anchorbound Rod", pos = Vector3.new(-1208.5, 56.3, 1646.2)},
        {name = "Blazeshark Rod", pos = Vector3.new(-8.4, 53.9, 6.7)},
        {name = "Kraken Rod", pos = Vector3.new(1543.8, 73.4, 1490.9)},
        {name = "Ascendant Bamboo Rod", pos = Vector3.new(-1360.6, 140.6, 31.0)},
        {name = "Lifebloom Rod", pos = Vector3.new(-114.9, 74.9, -1533.2)},
        {name = "Demonic Rod", pos = Vector3.new(1181.9, 82.9, -1243.8)}
    }

    for _, sr in ipairs(secretRods) do
        Components.CreateButtonRow(sRodCard, sr.name, "Bay đến tọa độ lấy cần: " .. sr.name, "Bay Đến", function()
            Teleport.To(sr.pos + Vector3.new(0, 3, 0))
            Utils.ShowNotification("Cần Bí Mật", "Đã bay đến vị trí " .. sr.name .. "!", "SUCCESS", 4)
        end)
    end

    -- ============================================================
    -- 5. DỊCH CHUYỂN ĐẾN NGƯỜI CHƠI TRONG MAP
    -- ============================================================
    Components.CreateCategoryHeader(parent, "👥 Dịch Chuyển Đến Người Chơi Trong Map")
    local srvCard = Components.CreateCardGroup(parent)

    local playerLookup = {}
    local selectedPlayerKey = nil

    local function BuildPlayerList()
        local list = {}
        table.clear(playerLookup)
        local myChar = LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local myPos = myRoot and myRoot.Position

        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then
                local distStr = ""
                if myPos and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                    local d = math.floor((p.Character.HumanoidRootPart.Position - myPos).Magnitude)
                    distStr = string.format(" [%dm]", d)
                end
                local key = string.format("%s (@%s)%s", p.DisplayName, p.Name, distStr)
                table.insert(list, key)
                playerLookup[key] = p
            end
        end

        if #list == 0 then
            table.insert(list, "Không có người chơi khác")
        end
        return list
    end

    local initialPlayerList = BuildPlayerList()
    selectedPlayerKey = initialPlayerList[1]

    local playerDropdown = Components.CreateDropdownRow(srvCard, "Chọn Người Chơi", "Danh sách người chơi đang có mặt trong server", initialPlayerList, selectedPlayerKey, function(v)
        selectedPlayerKey = v
    end)

    local function RefreshPlayerDropdown()
        local newList = BuildPlayerList()
        if playerDropdown and playerDropdown.Refresh then
            playerDropdown.Refresh(newList, true)
            selectedPlayerKey = playerDropdown.Get and playerDropdown.Get() or newList[1]
        end
    end

    Components.CreateButtonRow(srvCard, "Bay Đến Người Chơi Đã Chọn", "Dịch chuyển tức thì đến ngay bên cạnh người chơi đang chọn", "🚀 Bay Đến", function()
        local targetPlayer = playerLookup[selectedPlayerKey]
        if not targetPlayer then
            local uName = selectedPlayerKey and selectedPlayerKey:match("@([%w_]+)")
            if uName then
                targetPlayer = Players:FindFirstChild(uName)
            end
        end

        if not targetPlayer or not targetPlayer.Parent then
            Utils.ShowNotification("Dịch Chuyển", "Vui lòng chọn người chơi hợp lệ!", "WARN", 3)
            RefreshPlayerDropdown()
            return
        end

        local tChar = targetPlayer.Character
        local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
        local myChar = LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")

        if myRoot and tRoot then
            myRoot.CFrame = tRoot.CFrame + Vector3.new(0, 2, 3)
            Utils.ShowNotification("Dịch Chuyển", "Đã bay đến người chơi: " .. targetPlayer.DisplayName, "SUCCESS", 4)
            RefreshPlayerDropdown()
        else
            Utils.ShowNotification("Dịch Chuyển", "Người chơi này chưa hồi sinh hoặc không có nhân vật!", "WARN", 3)
        end
    end)

    Components.CreateButtonRow(srvCard, "Làm Mới Danh Sách Người Chơi", "Cập nhật danh sách người chơi vừa tham gia hoặc rời server", "🔄 Làm Mới", function()
        RefreshPlayerDropdown()
        Utils.ShowNotification("Danh Sách", "Đã cập nhật danh sách người chơi trong map!", "INFO", 3)
    end)

    local lastTpTarget = nil
    Components.CreateButtonRow(srvCard, "Bay Đến Người Chơi Ngẫu Nhiên", "Dịch chuyển tức thì đến vị trí của một người chơi bất kỳ", "🎲 Ngẫu Nhiên", function()
        local targets = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                table.insert(targets, p)
            end
        end
        if #targets == 0 then
            Utils.ShowNotification("Dịch Chuyển", "Không tìm thấy người chơi nào khác trong server.", "WARN", 3)
            return
        end
        local pool = {}
        for _, p in ipairs(targets) do
            if not (#targets > 1 and p == lastTpTarget) then
                table.insert(pool, p)
            end
        end
        local selected = (#pool > 0 and pool[math.random(1, #pool)]) or targets[math.random(1, #targets)]
        lastTpTarget = selected
        local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if root and selected.Character and selected.Character:FindFirstChild("HumanoidRootPart") then
            root.CFrame = selected.Character.HumanoidRootPart.CFrame + Vector3.new(0, 2, 3)
            Utils.ShowNotification("Dịch Chuyển", "Đã bay đến người chơi: " .. selected.DisplayName, "SUCCESS", 4)
            RefreshPlayerDropdown()
        end
    end)

    -- ============================================================
    -- 6. DỊCH CHUYỂN ĐẾN 17 NPC NHIỆM VỤ
    -- ============================================================
    Components.CreateCategoryHeader(parent, "🧙 Dịch Chuyển Đến 17 NPC Nhiệm Vụ")
    local npcTeleCard = Components.CreateCollapsibleCardGroup(parent, "Danh Sách Tất Cả NPC Trong Game", true)

    local questNPCList = {
        { name="Ha Dieu De",            path="Function",  icon="🏆", role="Main Quest",          desc="Trả quest cá Rainbow Dragonfish & Heavenpiercer Turtle", island="Bamboo / Coconut / Frost" },
        { name="Giang Lao",             path="Function",  icon="🎣", role="Main Quest",          desc="NPC nhiệm vụ chính • Trả quest cá nặng", island="Bamboo / Mistpeak / World Angler" },
        { name="Sage Yijiu",            path="Function",  icon="🔮", role="Skill Shop + Quest",  desc="Bán skill Heavenpiercer & Pure Diamond • Trả quest Frost", island="Frost Isle / World Angler" },
        { name="Blind Grand Angler",    path="Function",  icon="👁️", role="Main Quest",          desc="Lão ngư ông mù • Trả quest mở khóa câu bí mật", island="Battlefield Isle" },
        { name="Duan Gan",              path="Function",  icon="🗡️", role="Main Quest",          desc="Võ sĩ gãy cần • Quest chính • Cần Huyết Long", island="Đảo chính" },
        { name="Bac Minh",              path="Function",  icon="⬆️", role="Skill Shop",          desc="Bán và nâng cấp kỹ năng câu cá bằng Gems", island="Đảo chính" },
        { name="Zeng Tianguo",          path="Function",  icon="⚡", role="Skill Upgrade",       desc="Nâng cấp kỹ năng đặc biệt", island="Perch / Sovereign" },
        { name="Tang Thien Quoc",       path="Function",  icon="🌟", role="Skill Upgrade",       desc="NPC nâng cấp kỹ năng cấp cao", island="Sovereign / Perch" },
        { name="Biao Di",               path="Function",  icon="🎯", role="Thợ Chế Cần Câu",    desc="Craft & mua bán cần câu các loại", island="Mọi đảo chính" },
        { name="Hua Heshang",           path="Function",  icon="🐉", role="Dragon Quest",        desc="Yêu cầu skill Dragon Subjugation", island="Đảo chính" },
        { name="The Shadow",            path="Function",  icon="🌑", role="Bí Mật / PVP",       desc="Nhiệm vụ bí mật và PVP arena đặc biệt", island="Đảo chính" },
        { name="Lao Ngo",               path="Function",  icon="👴", role="Quest Phụ",           desc="Lão Ngô • Cung cấp thông tin câu hiếm", island="Đảo chính" },
        { name="Nanjiang",              path="Function",  icon="🗺️", role="Quest Phụ",           desc="Nam Giang • Thông tin đảo và vị trí câu hiếm", island="Đảo chính" },
        { name="Giang Lao PVP",         path="Function",  icon="⚔️", role="PVP Arena",           desc="Đấu trường PVP câu cá • Nhận Stars đổi skin cần", island="Battlefield Isle" },
        { name="Battlefield Isle's Giang Lao", path="Function", icon="🏟️", role="Battlefield Quest", desc="Quest đấu trường Battlefield", island="Battlefield Isle" },
        { name="Ticket Quest Giver",    path="Function",  icon="🎫", role="Sự Kiện",             desc="Phát nhiệm vụ vé hàng ngày (Daily Tickets)", island="Đảo chính" },
        { name="Nana",                  path="SellFish",  icon="🐟", role="Bán Cá",             desc="Thu mua cá nhanh lấy Gems", island="Mọi đảo" },
        { name="Ba Chang",              path="BuyBait",   icon="🪱", role="Bán Mồi Câu",        desc="Bán mồi câu cơ bản giá rẻ", island="Đảo chính / Coconut" },
    }

    local function findNPCModel(npcName, npcPath)
        local npcFolder = Workspace:FindFirstChild("NPC")
        if npcFolder then
            local pathFolder = npcFolder:FindFirstChild(npcPath)
            if pathFolder then
                local found = pathFolder:FindFirstChild(npcName)
                if found and (found:FindFirstChild("HumanoidRootPart") or found:IsA("BasePart")) then
                    return found
                end
            end
            for _, sub in ipairs(npcFolder:GetChildren()) do
                local found = sub:FindFirstChild(npcName)
                if found then return found end
            end
        end
        return Workspace:FindFirstChild(npcName, true)
    end

    for _, npc in ipairs(questNPCList) do
        local title = string.format("%s %s [%s]", npc.icon, npc.name, npc.role)
        local desc = string.format("%s\n📍 %s", npc.desc, npc.island)
        Components.CreateButtonRow(npcTeleCard, title, desc, "Bay Đến", function()
            local char = LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root then
                Utils.ShowNotification("Lỗi", "Nhân vật chưa spawn!", "ERROR", 3)
                return
            end
            local model = findNPCModel(npc.name, npc.path)
            if model then
                local npcRoot = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChildWhichIsA("BasePart")
                if npcRoot then
                    root.CFrame = CFrame.new(npcRoot.Position + Vector3.new(0, 3, 3))
                    Utils.ShowNotification("✅ Đến " .. npc.name, "Đã bay đến NPC " .. npc.name .. "!", "SUCCESS", 4)
                    return
                end
            end
            Utils.ShowNotification("❌ Không Tìm Thấy", "NPC '" .. npc.name .. "' không có trong map lúc này.", "WARN", 4)
        end)
    end

    -- ============================================================
    -- 7. DỊCH CHUYỂN ĐẾN ĐẠO SĨ (TAOIST & MAOSHAN)
    -- ============================================================
    Components.CreateCategoryHeader(parent, "📜 Dịch Chuyển Đến Đạo Sĩ (Taoist & Maoshan)")
    local taoistTeleCard = Components.CreateCardGroup(parent)

    Components.CreateButtonRow(taoistTeleCard, "📜 Bay Đến Đạo Sĩ (Taoist)", "Dịch chuyển tức thì đến NPC Đạo Sĩ nếu có trong server", "Bay Đến", function()
        local tInst, tName = Spirits.ScanForTaoistNPC()
        if tInst then
            local ok = Spirits.TeleportToNPC(tInst)
            if ok then
                Utils.ShowNotification("Đạo Sĩ (Taoist)", "Đã dịch chuyển đến vị trí " .. tostring(tName) .. "!", "SUCCESS", 5)
            else
                Utils.ShowNotification("Đạo Sĩ (Taoist)", "Không lấy được tọa độ Đạo Sĩ.", "WARN", 3)
            end
        else
            Utils.ShowNotification("Đạo Sĩ (Taoist)", "Server này hiện chưa có Đạo Sĩ (Taoist)! Hãy bật 'Đổi Server Tìm Taoist'.", "WARN", 5)
        end
    end)

    Components.CreateButtonRow(taoistTeleCard, "✨ Bay Đến Đạo Sĩ Maoshan", "Dịch chuyển tức thì đến NPC Đạo Sĩ Maoshan nếu có trong server", "Bay Đến", function()
        local mInst, mName = Spirits.ScanForMaoshanNPC()
        if mInst then
            local ok = Spirits.TeleportToNPC(mInst)
            if ok then
                Utils.ShowNotification("Đạo Sĩ Maoshan", "Đã dịch chuyển đến vị trí " .. tostring(mName) .. "!", "SUCCESS", 5)
            else
                Utils.ShowNotification("Đạo Sĩ Maoshan", "Không lấy được tọa độ Đạo Sĩ Maoshan.", "WARN", 3)
            end
        else
            Utils.ShowNotification("Đạo Sĩ Maoshan", "Server này hiện chưa có Đạo Sĩ Maoshan! Hãy bật 'Đổi Server Tìm Maoshan'.", "WARN", 5)
        end
    end)

    -- ============================================================
    -- 8. CHUYỂN SERVER (SERVER HOP)
    -- ============================================================
    Components.CreateCategoryHeader(parent, "🌐 Chuyển Server (Server Hop)")
    local cardHop = Components.CreateCardGroup(parent)
    Components.CreateButtonRow(cardHop, "Chuyển Server Khác (Hop Server)", "Tìm server ngẫu nhiên còn chỗ và chuyển vào", "Đổi Server", function()
        Teleport.ServerHop()
    end)
end

return TabDichChuyen

end

__modules["ui.tabs.tab_nhan_vat"] = function()
--[[
    v2/ui/tabs/tab_nhan_vat.lua
    Character Physics, Fly, Noclip, Walk on Water, Anti-AFK & Visual Spoofing
--]]

local Components = __require("ui.components")
local ConfigModule = __require("core.config")
local Config = ConfigModule.Config
local Character = __require("features.character")
local Spoof = __require("features.spoof")
local Utils = __require("core.utils")

local TabNhanVat = {}

function TabNhanVat.Render(parent)
    Components.CreateCategoryHeader(parent, "🏃 Di Chuyển & Thể Chất")
    local cardMove = Components.CreateCardGroup(parent)

    Components.CreateToggleRow(cardMove, "Tăng Tốc Độ Chạy (Speed)", "Tăng tốc độ di chuyển của nhân vật", Config.WalkSpeedEnabled, function(v)
        Config.WalkSpeedEnabled = v
        Character.ApplySpeed(Config)
    end)
    Components.CreateSliderRow(cardMove, "Chỉnh Tốc Độ", "Tốc độ chạy mong muốn", 16, 120, Config.WalkSpeedValue or 16, false, "", function(v)
        Config.WalkSpeedValue = v
        Character.ApplySpeed(Config)
    end)

    Components.CreateToggleRow(cardMove, "Bay Lượn Tự Do (Fly)", "Bay lượn tự do phím WASD + Space/Shift", Config.FlyEnabled, function(v)
        Config.FlyEnabled = v
    end)
    Components.CreateSliderRow(cardMove, "Tốc Độ Bay", "Tốc độ bay trên không trung", 20, 150, Config.FlySpeed or 50, false, "", function(v)
        Config.FlySpeed = v
    end)

    Components.CreateToggleRow(cardMove, "Đi Xuyên Tường (Noclip)", "Đi xuyên qua mọi vật cản và địa hình", Config.Noclip, function(v)
        Config.Noclip = v
    end)
    Components.CreateToggleRow(cardMove, "Đi Trên Mặt Nước", "Tạo bệ vô hình để đứng trên mặt biển", Config.WalkOnWater, function(v)
        Config.WalkOnWater = v
        Character.ApplyWalkOnWater(Config)
    end)
    Components.CreateToggleRow(cardMove, "Nhảy Vô Hạn (Infinite Jump)", "Nhảy liên tục trên không", Config.InfiniteJump, function(v)
        Config.InfiniteJump = v
    end)

    Components.CreateCategoryHeader(parent, "🎭 Ảo Hoá Tài Sản (Visual Spoof)")
    local cardSpoof = Components.CreateCardGroup(parent)

    local targetGems = Spoof.fakeGems or 0
    local targetTickets = Spoof.fakeTicket or 0

    Components.CreateInputRow(cardSpoof, "Số Gems Ảo", "Nhập số lượng Gems muốn hiển thị trên màn hình", tostring(targetGems), function(v)
        local n = tonumber(v)
        if n and n >= 0 then targetGems = n end
    end, nil, "VD: 9999999")

    Components.CreateButtonRow(cardSpoof, "Áp Dụng Gems Ảo", "Đổi giao diện hiển thị Gems sang con số trên", "Đổi Gems", function()
        Spoof.fakeGems = targetGems
        Spoof.Save()
        Spoof.Apply(false)
        Utils.ShowNotification("Visual Spoof", "Đã ảo hóa Gems thành: " .. Spoof.FormatWithSpaces(targetGems), "SUCCESS", 4)
    end)

    Components.CreateInputRow(cardSpoof, "Số Vé Ảo (Tickets)", "Nhập số lượng vé muốn hiển thị", tostring(targetTickets), function(v)
        local n = tonumber(v)
        if n and n >= 0 then targetTickets = n end
    end, nil, "VD: 100")

    Components.CreateButtonRow(cardSpoof, "Áp Dụng Vé Ảo", "Đổi giao diện hiển thị Vé sang con số trên", "Đổi Vé", function()
        Spoof.fakeTicket = targetTickets
        Spoof.Save()
        Spoof.Apply(false)
        Utils.ShowNotification("Visual Spoof", "Đã ảo hóa Vé thành: " .. tostring(targetTickets), "SUCCESS", 4)
    end)

    Components.CreateButtonRow(cardSpoof, "Khôi Phục Thực Tế (Reset)", "Trả lại số Gems và Vé thật của tài khoản", "Reset", function()
        Spoof.fakeGems = 0
        Spoof.fakeTicket = 0
        Spoof.Save()
        Spoof.Apply(true)
        Utils.ShowNotification("Visual Spoof", "Đã khôi phục số dư thật!", "INFO", 4)
    end)

    Components.CreateCategoryHeader(parent, "🛡️ Hệ Thống & Chống Treo")
    local cardSystem = Components.CreateCardGroup(parent)
    Components.CreateToggleRow(cardSystem, "Chống Văng Game (Anti-AFK)", "Ngăn chặn bị kick khi treo máy qua đêm", Config.AntiAFK, function(v)
        Config.AntiAFK = v
    end)
    Components.CreateToggleRow(cardSystem, "Tự Động Kết Nối Lại", "Tự động rejoin nếu bị ngắt kết nối mạng", Config.AutoRejoin, function(v)
        Config.AutoRejoin = v
    end)
end

return TabNhanVat

end

__modules["ui.tabs.tab_nhiem_vu"] = function()
--[[
    v2/ui/tabs/tab_nhiem_vu.lua
    Daily Tickets Engine, Settings, Spots Management & Remote Actions
--]]

local Components = __require("ui.components")
local ConfigModule = __require("core.config")
local Config = ConfigModule.Config
local Quest = __require("features.quest")
local Services = __require("core.services")
local LocalPlayer = Services.LocalPlayer
local Utils = __require("core.utils")

local TabNhiemVu = {}

function TabNhiemVu.Render(parent)
    Components.CreateCategoryHeader(parent, "📊 Trạng Thái Vé Nhiệm Vụ")
    local cardStatus = Components.CreateCardGroup(parent)

    local statusRow = Components.CreateInfoRow(cardStatus, "Tiến Độ Nhiệm Vụ", Quest.state.statusText)
    task.spawn(function()
        while true do
            task.wait(1.5)
            if statusRow and statusRow.Set then
                statusRow.Set(Quest.state.statusText)
            end
        end
    end)

    Components.CreateCategoryHeader(parent, "🎟️ Tự Động Nộp & Làm Vé Nhiệm Vụ (Tickets)")
    local cardTicket = Components.CreateCardGroup(parent)

    Components.CreateToggleRow(cardTicket, "Tự Động Nộp Vé Nhiệm Vụ (Tickets)", "Tự động nhận, thực hiện và trả nhiệm vụ vé hàng ngày", Config.AutoTicketQuest, function(v) Config.AutoTicketQuest = v end)
    Components.CreateDropdownRow(cardTicket, "Chọn Độ Khó Vé Nhiệm Vụ", "Độ khó nhiệm vụ muốn ưu tiên nhận", {"Hard", "Easy"}, Config.TicketDifficulty, function(v) Config.TicketDifficulty = v end)
    Components.CreateDropdownRow(cardTicket, "Chế Độ Nhiệm Vụ", "Chế độ lọc loại nhiệm vụ ưu tiên", {"Tự Động (Auto Detect)", "100 Cá (Fish 100)", "100 Chiêu (Skill 100)", "15m Cá (Size 15m)", "100 Mồi (Bait 100)"}, Config.TicketQuestMode, function(v) Config.TicketQuestMode = v end)
    Components.CreateDropdownRow(cardTicket, "Mồi Cho Nhiệm Vụ 100 Mồi", "Loại mồi dùng khi làm quest 100 mồi", {"Basic Bait", "Ancestral Bait", "Secret Bait"}, Config.TicketBaitChoice, function(v) Config.TicketBaitChoice = v end)
    Components.CreateDropdownRow(cardTicket, "Chiêu Dùng Cho Nhiệm Vụ 100 Skill", "Chiêu spam cho nhiệm vụ 100 skill", {"Chiêu Z", "Chiêu X", "Chiêu C", "Chiêu V"}, Config.TicketSkillKey, function(v) Config.TicketSkillKey = v end)
    Components.CreateDropdownRow(cardTicket, "Chiêu Giật Nhanh Cho 100 Con Cá", "Chiêu kết liễu nhanh cho nhiệm vụ 100 cá", {"Chiêu Z", "Chiêu X", "Chiêu C", "Chiêu V"}, Config.TicketQuickSkill, function(v) Config.TicketQuickSkill = v end)
    Components.CreateToggleRow(cardTicket, "Tự Bán Cá Khi Đầy Balo (Vé NV)", "Tự bán cá giải phóng chỗ trống khi đang làm vé", Config.TicketAutoSellFull, function(v) Config.TicketAutoSellFull = v end)
    Components.CreateToggleRow(cardTicket, "Tự Về Home Spot Khi Xong Nhiệm Vụ", "Tự bay về điểm farm chính khi hết vé", Config.TicketReturnHomeWhenDone, function(v) Config.TicketReturnHomeWhenDone = v end)
    Components.CreateToggleRow(cardTicket, "Tự Động Quăng Cần Tại Home Spot", "Tiếp tục farm cá tại Home Spot khi hoàn thành vé", Config.TicketAutoCastAtHome, function(v) Config.TicketAutoCastAtHome = v end)
    Components.CreateToggleRow(cardTicket, "Nhận & Nộp Vé Từ Xa (Remote)", "Thực hiện nhận và trả nhiệm vụ từ xa", Config.TicketRemoteClaim, function(v) Config.TicketRemoteClaim = v end)
    Components.CreateToggleRow(cardTicket, "Tự Động Nhận Thưởng Hàng Ngày (Daily)", "Tự động nhận quà đăng nhập mỗi ngày", Config.AutoClaimDaily, function(v) Config.AutoClaimDaily = v end)

    Components.CreateCategoryHeader(parent, "⚡ Thao Tác Nhanh")
    local cardActions = Components.CreateCardGroup(parent)

    Components.CreateButtonRow(cardActions, "Nộp Vé Ngay Lập Tức", "Dịch chuyển tức thì đến NPC và nộp vé hoàn thành", "Nộp Vé", function()
        Utils.ShowNotification("Nhiệm Vụ Vé", "Đang tiến hành nộp vé...", "INFO", 3)
        task.spawn(function()
            Quest.InteractNPC(true, Config)
        end)
    end)

    Components.CreateButtonRow(cardActions, "Nhận Vé Mới Ngay", "Dịch chuyển đến NPC và nhận vé nhiệm vụ mới", "Nhận Vé", function()
        Utils.ShowNotification("Nhiệm Vụ Vé", "Đang tiến hành nhận vé mới...", "INFO", 3)
        task.spawn(function()
            Quest.InteractNPC(false, Config)
        end)
    end)

    Components.CreateButtonRow(cardActions, "Bay Đến NPC Vé", "Dịch chuyển tức thì đến vị trí của NPC trao vé", "Bay Đến", function()
        Quest.TeleportToNPC()
        Utils.ShowNotification("Nhiệm Vụ Vé", "Đã bay đến vị trí NPC nhận vé!", "SUCCESS", 4)
    end)

    Components.CreateCategoryHeader(parent, "📍 Cài Đặt Điểm Câu Cho Từng Loại Vé")
    local cardSpots = Components.CreateCardGroup(parent)

    Components.CreateButtonRow(cardSpots, "Lưu Vị Trí Hiện Tại Làm Điểm 100 Cá", "Đặt tọa độ đứng hiện tại làm điểm farm 100 con cá", "Lưu 100 Cá", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            Quest.state.spot100Fish = root.Position
            Quest.SaveSpots()
            Utils.ShowNotification("Điểm Câu", "Đã lưu điểm làm nhiệm vụ 100 con cá!", "SUCCESS", 4)
        end
    end)

    Components.CreateButtonRow(cardSpots, "Lưu Vị Trí Hiện Tại Làm Điểm 1.5M Cá", "Đặt tọa độ đứng hiện tại làm điểm farm cá 1.5M (Map 9)", "Lưu 1.5M Cá", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            Quest.state.spot15MFish = root.Position
            Quest.SaveSpots()
            Utils.ShowNotification("Điểm Câu", "Đã lưu điểm làm nhiệm vụ cá 1.5M!", "SUCCESS", 4)
        end
    end)

    Components.CreateButtonRow(cardSpots, "Lưu Vị Trí Hiện Tại Làm Điểm 100 Mồi", "Đặt tọa độ đứng hiện tại làm điểm farm tiêu thụ 100 mồi", "Lưu 100 Mồi", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            Quest.state.spot100Bait = root.Position
            Quest.SaveSpots()
            Utils.ShowNotification("Điểm Câu", "Đã lưu điểm làm nhiệm vụ 100 mồi!", "SUCCESS", 4)
        end
    end)
end

return TabNhiemVu

end

__modules["ui.tabs.tab_san_boss"] = function()
--[[
    v2/ui/tabs/tab_san_boss.lua
    Secret Boss Hunter, Fast Skip, Spot Allocation, Jitter, Weather Server Hop & Totems
--]]

local Components = __require("ui.components")
local State = __require("core.state")
local ConfigModule = __require("core.config")
local Config = ConfigModule.Config
local Boss = __require("features.boss")
local Weather = __require("features.weather")
local Services = __require("core.services")
local LocalPlayer = Services.LocalPlayer
local Utils = __require("core.utils")

local TabSanBoss = {}

function TabSanBoss.Render(parent)
    Components.CreateCategoryHeader(parent, "👹 Tự Động Săn Boss & Đổi Server")
    local bossCoreCard = Components.CreateCardGroup(parent)

    Components.CreateToggleRow(bossCoreCard, "Bật Chế Độ Săn Boss (Tự Quăng Cần & Lọc Cá)", "Tự động thả cần câu và săn boss tại chỗ", Config.AutoHuntBoss, function(v) Config.AutoHuntBoss = v end)
    Components.CreateToggleRow(bossCoreCard, "Bật Săn Secret Boss (Chat Sniper)", "Tự động dịch chuyển đến đảo ngay khi có thông báo chat xuất hiện Boss", Config.AutoChatSecretBoss, function(v) Config.AutoChatSecretBoss = v end)
    Components.CreateToggleRow(bossCoreCard, "Giật Cần Thả Lại (Fast Skip Cá Thường)", "Tự động giật lại cần ngay lập tức nếu cá cắn câu không phải Boss được chọn", Config.FastSkipNonBoss, function(v) Config.FastSkipNonBoss = v end)
    Components.CreateToggleRow(bossCoreCard, "Kiểm Tra Lực Cần (Power Check)", "Chỉ săn khi đủ lực cần yêu cầu của từng hòn đảo", Config.SecretBossCheckPower, function(v) Config.SecretBossCheckPower = v end)
    Components.CreateToggleRow(bossCoreCard, "Hiện Bảng Sát Thương Boss (% HP)", "Hiển thị bảng DPS % máu khi nhiều người cùng pem Boss", Config.ShowBossDpsMeter, function(v) Config.ShowBossDpsMeter = v end)
    Components.CreateToggleRow(bossCoreCard, "Tự Đổi Server Khi Hết Boss (Auto-Hop)", "Tự chuyển server mới khi boss biến mất", Config.AutoServerHopOnDespawn, function(v) Config.AutoServerHopOnDespawn = v end)
    Components.CreateToggleRow(bossCoreCard, "Tự Về Vị Trí Farm Khi Hết Boss / Clear", "Quay lại điểm câu farm chính sau khi săn boss xong", Config.ReturnToHomeWhenClear, function(v) Config.ReturnToHomeWhenClear = v end)

    Components.CreateCategoryHeader(parent, "📍 Phân Bổ Điểm Đứng & Chống Trùng Tọa Độ")
    local spotCard = Components.CreateCardGroup(parent)

    Components.CreateDropdownRow(spotCard, "Chế Độ Chọn Điểm Câu Boss", "Phân chia điểm câu an toàn tránh giẫm chân bot khác", {"Tự Động (Theo Acc)", "Cố Định"}, Config.BossSpotAllocationMode or "Tự Động (Theo Acc)", function(v) Config.BossSpotAllocationMode = v end)
    Components.CreateToggleRow(spotCard, "Bật Jitter Dịch Chuyển (Lệch Tọa Độ)", "Tạo độ lệch nhẹ ngẫu nhiên khi bay tránh trùng lặp tuyệt đối", Config.BossTeleportJitter, function(v) Config.BossTeleportJitter = v end)
    Components.CreateSliderRow(spotCard, "Khoảng Cách Jitter", "Bán kính độ lệch tọa độ khi dịch chuyển", 0.5, 5.0, Config.BossTeleportJitterDist or 1.0, false, " studs", function(v) Config.BossTeleportJitterDist = v end)

    local islandList = {"Đảo Tre (Bamboo Isle)", "Đảo Quả Dừa (Coconut Isle)", "Đảo Hổ Phách (Amber Isle)", "Đảo Băng (Frost Isle)", "Đảo Bão Tố (Storm Isle)"}
    local selectedIsland = Config.SelectedCustomSpotIsland or islandList[1]
    local selectedSlot = Config.SelectedCustomSpotSlot or 1

    Components.CreateDropdownRow(spotCard, "Chọn Hòn Đảo", "Hòn đảo muốn tùy chỉnh điểm câu boss", islandList, selectedIsland, function(v)
        selectedIsland = v
        Config.SelectedCustomSpotIsland = v
    end)
    Components.CreateDropdownRow(spotCard, "Chọn Slot Điểm Câu (1-5)", "Vị trí slot điểm an toàn", {"1", "2", "3", "4", "5"}, tostring(selectedSlot), function(v)
        selectedSlot = tonumber(v) or 1
        Config.SelectedCustomSpotSlot = selectedSlot
    end)
    Components.CreateButtonRow(spotCard, "Lưu Vị Trí Hiện Tại Cho Slot Này", "Lưu tọa độ đứng hiện tại làm điểm an toàn cho hòn đảo đã chọn", "Lưu Slot", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            Boss.SetCustomSpot(selectedIsland, selectedSlot, root.Position)
            Utils.ShowNotification("Điểm Boss", string.format("Đã lưu Slot %d cho %s!", selectedSlot, selectedIsland), "SUCCESS", 4)
        end
    end)

    -- Weather Server Hop Card
    Components.CreateCategoryHeader(parent, "🌪️ Tự Động Tìm Server Thời Tiết")
    local weatherCard = Components.CreateCardGroup(parent)

    Components.CreateToggleRow(weatherCard, "Tự Động Tìm Server Thời Tiết", "Tự động đổi server liên tục đến khi gặp thời tiết mong muốn", Config.AutoWeatherHop, function(v)
        Config.AutoWeatherHop = v
        Weather.SaveWeatherHopState(Config)
    end)
    Components.CreateDropdownRow(weatherCard, "Thời Tiết Cần Tìm", "Loại thời tiết muốn bot tìm kiếm", Weather.weatherChoices, Config.TargetWeather or Weather.weatherChoices[1], function(v)
        Config.TargetWeather = v
    end)
    Components.CreateToggleRow(weatherCard, "Tự Động Câu / Săn Khi Tìm Thấy", "Bắt đầu câu ngay khi vào server có thời tiết mục tiêu", Config.WeatherHopAutoFish, function(v) Config.WeatherHopAutoFish = v end)
    Components.CreateToggleRow(weatherCard, "Gửi Webhook Khi Tìm Thấy Server", "Gửi thông báo JobID vào Discord/Telegram", Config.WeatherHopAlertWebhook, function(v) Config.WeatherHopAlertWebhook = v end)

    Components.CreateCategoryHeader(parent, "🌩️ Bàn Thờ Thời Tiết (Weather Totems)")
    local totemCard = Components.CreateCardGroup(parent)

    for _, t in ipairs(Weather.totems) do
        Components.CreateButtonRow(totemCard, t.name, "Bay đến và kích hoạt: " .. t.weather, "Kích Hoạt", function()
            Weather.InteractTotem(t)
        end)
    end

    Components.CreateCategoryHeader(parent, "🎯 Mục Tiêu Secret Boss (Bật / Tắt Từng Con)")
    local targetsGroup = Components.CreateCollapsibleCardGroup(parent, "Danh Sách Boss Mục Tiêu", true)

    local bossList = {
        "Verdant Alligator Gar", "Verdant Grouper", "Verdant Bonefang", "Crimson Bonefang",
        "Scarlet Fish", "Elder Scarlet Fish", "Crimson Electric Eel", "Golden Dragonfish", "Rainbow Dragonfish",
        "Flying Fish Emperor", "Flying Fish Empress", "Draconic Koi", "Sanguine Fish",
        "Tigerfang Whale", "Heavenpiercer Turtle", "Heaven Piercer Turtle", "Reborn Puffer Beast",
        "Frost Kingfish", "Frost Queenfish", "Mountain Dragonwhale", "Mirage Lanternfish", "Nameless Octoparasite"
    }

    for _, bossName in ipairs(bossList) do
        local initVal = (Config.SecretBossTargets[bossName] ~= false)
        local ctrl = Components.CreateToggleRow(targetsGroup, bossName, "Săn " .. bossName, initVal, function(v)
            Config.SecretBossTargets[bossName] = v
            ConfigModule.SaveBossTargets()
        end)
        State.bossTogglesMap[bossName] = ctrl
    end

    -- Boss Bạch Tuộc Bí Mật
    Components.CreateCategoryHeader(parent, "🐙 Boss Bạch Tuộc Bí Mật (Octoparasite)")
    local octoCard = Components.CreateCardGroup(parent)
    Components.CreateToggleRow(octoCard, "Tự Chơi Minigame (Rhythm Bot)", "Bot tự động gõ nhịp chuẩn Perfect 100%", Config.OctoAutoMinigame, function(v) Config.OctoAutoMinigame = v end)
    Components.CreateButtonRow(octoCard, "Bay Đến Phao Boss Bạch Tuộc", "Dịch chuyển đến phao triệu hồi Secret Boss giữa biển", "Bay Đến", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(1608.2, 5.0, -218.3)
            Utils.ShowNotification("Dịch Chuyển", "Đã đến Phao Boss Bạch Tuộc!", "SUCCESS")
        end
    end)
    Components.CreateButtonRow(octoCard, "Bay Đến Vùng Lòng Đất", "Dịch chuyển đến vùng đất câu cá ngầm bí mật", "Bay Đến", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(112.5, -330.0, -30.8)
            Utils.ShowNotification("Dịch Chuyển", "Đã đến Vùng Câu Cá Ngầm!", "SUCCESS")
        end
    end)

    -- Cần Câu Cần Ráp (Rod Crafting Guide)
    Components.CreateCategoryHeader(parent, "🎣 Cần Câu Cần Ráp (Rod Crafting Guide)")
    local rodGuideCard = Components.CreateCollapsibleCardGroup(parent, "Hướng Dẫn Ráp Cần & Bộ Lọc Nhanh", false)

    local rodRecipes = {
        {
            rod = "Heavenpiercer Rod",
            desc = "Cần Thiên Xuyên (Cao Cấp)",
            bosses = {"Flying Fish Emperor", "Flying Fish Empress", "Rainbow Dragonfish", "Heavenpiercer Turtle"},
            notes = {
                ["Flying Fish Emperor"]  = "Nguyên liệu chính",
                ["Flying Fish Empress"]  = "Nguyên liệu chính",
                ["Rainbow Dragonfish"]   = "Nguyên liệu + Trả Quest",
                ["Heavenpiercer Turtle"] = "Nguyên liệu + Mồi Rainbow",
            }
        },
        {
            rod = "Pure Diamond Rod",
            desc = "Cần Kim Cương Thuần (Cao Cấp)",
            bosses = {"Frost Kingfish", "Frost Queenfish", "Sanguine Fish", "Draconic Koi"},
            notes = {
                ["Frost Kingfish"]  = "Nguyên liệu + Mồi Frost",
                ["Frost Queenfish"] = "Nguyên liệu chính",
                ["Sanguine Fish"]   = "Nguyên liệu chính",
                ["Draconic Koi"]    = "Nguyên liệu phụ",
            }
        },
        {
            rod = "Sacred Bamboo Rod",
            desc = "Cần Trúc Thánh (Cao Cấp)",
            bosses = {"Nameless Octoparasite", "Reborn Puffer Beast", "Mountain Dragonwhale"},
            notes = {
                ["Nameless Octoparasite"] = "Nguyên liệu + Trả Quest Đạo Sĩ",
                ["Reborn Puffer Beast"]   = "Nguyên liệu + Trả Quest",
                ["Mountain Dragonwhale"]  = "Nguyên liệu + Mồi Nameless",
            }
        },
        {
            rod = "Rainbow Bait (Mồi)",
            desc = "Mồi Rainbow Bait (Gọi Boss Rùa)",
            bosses = {"Crimson Electric Eel", "Colossal Tigerfish", "Golden Guardian Fish"},
            notes = {
                ["Crimson Electric Eel"]  = "Nguyên liệu chính",
            }
        },
        {
            rod = "Nameless Bait (Mồi)",
            desc = "Mồi Nameless Bait (Gọi Bạch Tuộc)",
            bosses = {"Mirage Lanternfish", "Tiger Mirefish", "Octoparasitic Fish"},
            notes = {
                ["Mirage Lanternfish"]  = "Nguyên liệu chính",
            }
        }
    }

    for _, recipe in ipairs(rodRecipes) do
        Components.CreateInfoRow(rodGuideCard, "🪝 " .. recipe.rod, recipe.desc)
        Components.CreateButtonRow(rodGuideCard,
            "Ưu Tiên Chỉ Săn Cho: " .. recipe.rod,
            "Tắt hết boss khác, chỉ bật những boss cần cho " .. recipe.rod,
            "⚡ Lọc Boss",
            function()
                for bName, _ in pairs(Config.SecretBossTargets) do
                    Config.SecretBossTargets[bName] = false
                    if State.bossTogglesMap[bName] and State.bossTogglesMap[bName].Set then
                        pcall(function() State.bossTogglesMap[bName].Set(false, true) end)
                    end
                end
                for _, bName in ipairs(recipe.bosses) do
                    Config.SecretBossTargets[bName] = true
                    if State.bossTogglesMap[bName] and State.bossTogglesMap[bName].Set then
                        pcall(function() State.bossTogglesMap[bName].Set(true, true) end)
                    end
                end
                ConfigModule.SaveBossTargets()
                Utils.ShowNotification("Lọc Boss", "Đã bật mục tiêu cho: " .. recipe.rod, "SUCCESS", 5)
            end
        )
    end

    Components.CreateButtonRow(rodGuideCard, "Bật Lại Tất Cả Secret Boss", "Khôi phục lại toàn bộ danh sách secret boss", "Bật Tất Cả", function()
        for bName, _ in pairs(Config.SecretBossTargets) do
            Config.SecretBossTargets[bName] = true
            if State.bossTogglesMap[bName] and State.bossTogglesMap[bName].Set then
                pcall(function() State.bossTogglesMap[bName].Set(true, true) end)
            end
        end
        ConfigModule.SaveBossTargets()
        Utils.ShowNotification("Boss Targets", "Đã bật lại toàn bộ mục tiêu Secret Boss!", "SUCCESS", 4)
    end)

    -- Đấu Trường Boss Enzo
    Components.CreateCategoryHeader(parent, "⚔️ Đấu Trường Boss Enzo")
    local enzoCard = Components.CreateCardGroup(parent)
    Components.CreateToggleRow(enzoCard, "Tự Động Săn Boss (Enzo)", "Liên tục triệu hồi và câu boss Enzo", Config.AutoFarmBoss, function(v) Config.AutoFarmBoss = v end)
    Components.CreateToggleRow(enzoCard, "Tự Săn Secret Boss (Bạch Tuộc)", "Tự chế mồi Nameless Bait, triệu hồi và tiêu diệt", Config.AutoFarmSecretBoss, function(v) Config.AutoFarmSecretBoss = v end)
    Components.CreateButtonRow(enzoCard, "Bay Đến Boss Enzo", "Dịch chuyển trực tiếp đến đấu trường Enzo", "Bay Đến", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(-115.3, 9.2, 1349.5)
            Utils.ShowNotification("Dịch Chuyển", "Đã đến Đấu trường Boss Enzo!", "SUCCESS")
        end
    end)
end

return TabSanBoss

end

__modules["ui.tabs.tab_shop"] = function()
--[[
    v2/ui/tabs/tab_shop.lua
    Auto Sell with Advanced Protection Filters, Bait Crafting/Buying & Rod Shop
--]]

local Components = __require("ui.components")
local ConfigModule = __require("core.config")
local Config = ConfigModule.Config
local Shop = __require("features.shop")
local Services = __require("core.services")
local LocalPlayer = Services.LocalPlayer
local Events = Services.Events
local Utils = __require("core.utils")

local TabShop = {}

function TabShop.Render(parent)
    Components.CreateCategoryHeader(parent, "💰 Kinh Tế & Tự Động Bán Cá")
    local sellCard = Components.CreateCardGroup(parent)

    Components.CreateToggleRow(sellCard, "Tự Động Bán Cá (Auto Sell)", "Tự động bán toàn bộ cá trong balo theo chu kỳ", Config.AutoSell, function(v) Config.AutoSell = v end)
    Components.CreateSliderRow(sellCard, "Thời Gian Giãn Cách Bán", "Chu kỳ số giây tự động bán cá 1 lần", 10, 300, Config.SellInterval, false, "s", function(v) Config.SellInterval = v end)

    Components.CreateButtonRow(sellCard, "Bán Ngay & Bay Đến Nana", "Dịch chuyển tức thì đến NPC Nana và bán cá an toàn", "Bán Ngay", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(-203.5, 7.3, 107.1)
            task.wait(0.3)
            Shop.ProtectAllInventoryItems(Config, false)
            if Events and Events:FindFirstChild("SellFish") then
                Events.SellFish:FireServer("All")
                Utils.ShowNotification("Bán Cá", "Đã bán cá cho NPC Nana thành công!", "SUCCESS", 4)
            end
        end
    end)

    local fishList = {
        "Verdant Alligator Gar", "Verdant Grouper", "Verdant Bonefang", "Crimson Bonefang",
        "Scarlet Fish", "Elder Scarlet Fish", "Crimson Electric Eel", "Golden Dragonfish", "Rainbow Dragonfish",
        "Flying Fish Emperor", "Flying Fish Empress", "Draconic Koi", "Sanguine Fish",
        "Tigerfang Whale", "Heavenpiercer Turtle", "Reborn Puffer Beast", "Frost Kingfish", "Frost Queenfish",
        "Mountain Dragonwhale", "Mirage Lanternfish", "Nameless Octoparasite"
    }

    Components.CreateToggleRow(sellCard, "Tự Động Khóa Cá Đột Biến", "Khóa mọi cá Shiny, Giant, Golden, Albino, Corrupted...", Config.AutoProtectMutations, function(v) Config.AutoProtectMutations = v end)
    Components.CreateToggleRow(sellCard, "Giữ Cá Theo Trọng Lượng", "Giữ lại mọi con cá có cân nặng vượt ngưỡng", Config.KeepFishOverWeight, function(v) Config.KeepFishOverWeight = v end)
    Components.CreateSliderRow(sellCard, "Ngưỡng Cân Nặng Giữ (kg)", "Mức cân nặng tối thiểu để giữ cá lại không bán", 100, 1000000, Config.MinWeightToKeep or 1000, true, " kg", function(v) Config.MinWeightToKeep = v end)
    Components.CreateToggleRow(sellCard, "Khóa Cá Quý (Auto Favourite)", "Bảo vệ cá quý hiếm đã chọn, không bao giờ bị bán nhầm", Config.AutoFavouriteFish, function(v) Config.AutoFavouriteFish = v end)
    Components.CreateDropdownRow(sellCard, "Chọn Cá Cần Khóa", "Loại cá cần bảo vệ không bán", fishList, Config.FavouriteFishName or fishList[1], function(v) Config.FavouriteFishName = v end)
    Components.CreateToggleRow(sellCard, "Chế Độ Cày Nguyên Liệu", "Giữ lại cá làm nguyên liệu chế mồi, không bán", Config.MaterialFarming, function(v) Config.MaterialFarming = v end)

    Components.CreateCategoryHeader(parent, "🪱 Tự Động Chế Mồi & Mua Mồi")
    local cardBait = Components.CreateCardGroup(parent)

    Components.CreateToggleRow(cardBait, "Tự Động Chế Mồi", "Tự động chế mồi khi đủ nguyên liệu", Config.AutoCraftBait, function(v) Config.AutoCraftBait = v end)
    Components.CreateDropdownRow(cardBait, "Chọn Mồi Cần Chế", "Loại mồi muốn tự động chế", {"Nameless Bait", "Abyssal Bait", "Kraken Bait", "Secret Bait"}, Config.CraftBaitName or "Nameless Bait", function(v) Config.CraftBaitName = v end)
    Components.CreateSliderRow(cardBait, "Số Lượng Chế Mỗi Lần", "Số lượng mồi chế mỗi lượt", 1, 10, Config.CraftAmount or 1, false, " cái", function(v) Config.CraftAmount = v end)

    Components.CreateToggleRow(cardBait, "Tự Động Mua Mồi", "Tự động mua mồi khi số lượng dưới ngưỡng", Config.AutoBuyBait, function(v) Config.AutoBuyBait = v end)
    Components.CreateDropdownRow(cardBait, "Chọn Mồi Cần Mua", "Loại mồi muốn tự động mua tại cửa hàng", {"Ancestral Bait", "Midnight Bait", "Basic Bait"}, Config.BuyBaitName or "Ancestral Bait", function(v) Config.BuyBaitName = v end)
    Components.CreateSliderRow(cardBait, "Số Lượng Mua Mỗi Lần", "Số lượng mua mỗi lần gửi yêu cầu", 1, 20, Config.BuyBaitAmount or 5, false, " cái", function(v) Config.BuyBaitAmount = v end)
    Components.CreateSliderRow(cardBait, "Ngưỡng Tự Mua (Khi Dưới)", "Khi số mồi trong túi ít hơn mức này sẽ mua thêm", 5, 50, Config.BuyBaitThreshold or 10, false, " cái", function(v) Config.BuyBaitThreshold = v end)
    Components.CreateCategoryHeader(parent, "🔮 Thương Nhân Kỹ Năng (Sage Yijiu)")
    local sageCard = Components.CreateCardGroup(parent)
    local sageSkills = {"One-Strike Heaven Gate", "Taijiquan Technique", "Infinite Sky Ascension", "Rolling Chaos", "Sever the Gate", "Phoenix Strike Art", "Skyfall Stomp", "Beastbreaker Cleave", "Demonfall Technique", "Dragon Strike"}
    local chosenSageSkill = sageSkills[1]
    Components.CreateDropdownRow(sageCard, "Chọn Kỹ Năng", "Kỹ năng muốn học từ NPC Sage Yijiu", sageSkills, chosenSageSkill, function(v) chosenSageSkill = v end)

    Components.CreateButtonRow(sageCard, "Bay Đến & Mua Kỹ Năng", "Dịch chuyển đến Sage Yijiu và mua chiêu thức", "Mua Chiêu", function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            root.CFrame = CFrame.new(-117.5, 6.8, 41.2)
            task.wait(0.3)
            if Events and Events:FindFirstChild("BuySkill") then
                Events.BuySkill:FireServer(chosenSageSkill)
                Utils.ShowNotification("Sage Yijiu", "Đã mua thành công kỹ năng: " .. chosenSageSkill, "SUCCESS", 4)
            end
        end
    end)

    Components.CreateCategoryHeader(parent, "🎰 Vòng Quay May Mắn (Auto Gacha)")
    local gachaCard = Components.CreateCardGroup(parent)
    Components.CreateDropdownRow(gachaCard, "Chọn Vòng Quay Gacha", "Vòng quay muốn rút thưởng", {"Taiji Banner", "Egoless Banner"}, Config.GachaBanner or "Taiji Banner", function(v) Config.GachaBanner = v end)
    Components.CreateSliderRow(gachaCard, "Số Vé Mỗi Lần Quay", "Số lượng vé dùng cho mỗi lượt rút thưởng", 1, 10, Config.GachaPullsPerAction or 1, false, " vé", function(v) Config.GachaPullsPerAction = v end)
    Components.CreateToggleRow(gachaCard, "Vòng Quay May Mắn (Auto Gacha)", "Tự động rút thưởng liên tục từ banner đã chọn", Config.AutoGacha, function(v) Config.AutoGacha = v end)

    Components.CreateCategoryHeader(parent, "🎣 Cửa Hàng Cần Câu (Rod Shop)")
    local rodShopCard = Components.CreateCollapsibleCardGroup(parent, "Danh Sách Cần Câu Có Thể Mua / Trang Bị", true)

    local rods = {
        { name = "Wooden Rod", price = "$0", power = 8 },
